/* MODULE gt04 · Bước 3 Đặt giả thuyết · Ưu tiên: làm gì trước khi tiền và người có hạn
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'gt04', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:gt04-01', skill:'measure', read:'6 phút', t:'Mười việc trên bảng, đội chỉ đủ sức làm ba: chọn thế nào?',
  situation:'Bạn phụ trách marketing cho một chuỗi 6 quán cà phê ở Đà Nẵng. Sau buổi họp, bảng trắng có 10 đầu việc: làm lại menu, chạy TikTok, mở thẻ thành viên, chụp lại ảnh món, sửa trang Google Maps… Đội có 2 người, mỗi tháng làm được khoảng 60 giờ cho việc mới. Ai cũng thấy việc của mình quan trọng.',
  concept:{ name:'Ma trận tác động × công sức',
    body:'Vẽ hai trục: <b>tác động</b> (việc này đổi được bao nhiêu kết quả mình cần) và <b>công sức</b> (giờ người, tiền, thời gian chờ). Mỗi việc là một chấm. Góc tác động cao – công sức thấp làm ngay. Tác động cao – công sức cao lên kế hoạch có mốc. Tác động thấp – công sức thấp chỉ làm khi rảnh. Tác động thấp – công sức cao thì bỏ. Điểm mấu chốt: tác động phải đo theo đúng một mục tiêu, không phải "nghe hay". Không có số liệu thì ước bằng một phép nhân thô — lượt tiếp cận × phần trăm thay đổi dự kiến — và ghi rõ đó là ước lượng.' },
  example:'Mục tiêu quý là tăng khách ghé lần đầu. Sửa Google Maps (thêm ảnh, giờ mở, trả lời đánh giá): khoảng 6 giờ. Ước tác động (số minh hoạ): mỗi tháng khoảng 300 lượt bấm chỉ đường, thêm ảnh tăng 10% thì được chừng 30 khách mới. Thẻ thành viên: 40 giờ, chủ yếu giữ khách cũ, tác động thấp với mục tiêu này. TikTok đều tay: 30 giờ/tháng, tác động có thể cao nhưng chưa chắc. Chọn: làm Maps ngay, đặt lịch TikTok có mốc đo sau 4 tuần rồi mới quyết giữ hay bỏ, cất thẻ thành viên sang quý sau. Tổng 36 giờ, còn 24 giờ dự phòng.',
  takeaway:'Chấm mỗi việc trên hai trục theo một mục tiêu duy nhất; làm góc tác động cao – công sức thấp trước.',
  apply:'Liệt kê 5 việc đang chờ trong đội bạn. Nói trong 60 giây: việc nào nằm góc "làm ngay", việc nào nên bỏ, và mục tiêu bạn dùng để chấm tác động.',
  mistakes:['Chấm tác động theo cảm giác "việc này hay" thay vì theo mục tiêu quý.','Quên tính công sức ẩn: chờ duyệt, chờ đối tác, sửa đi sửa lại.'],
  q:[
  { type:'mcq', stem:'Đội 2 người, 10 đầu việc, 60 giờ mỗi tháng. Theo bạn, bước đầu tiên hợp lý nhất là gì?',
    options:[{k:'a',t:'Chia đều 60 giờ cho cả 10 việc để không ai thấy việc mình bị bỏ rơi'},{k:'b',t:'Chốt một mục tiêu rồi chấm tác động và công sức của từng việc'},
             {k:'c',t:'Làm việc dễ nhất trước cho có đà, việc khó để dành cuối tháng'},{k:'d',t:'Hỏi mỗi người thích việc nào nhất rồi giao đúng sở thích'}],
    answer:'b', why:{a:'Mỗi việc chỉ được 6 giờ; phần lớn sẽ dở dang và không việc nào tạo ra kết quả.',
      b:'Đúng. Không có mục tiêu thì không chấm được tác động; không chấm thì chỉ còn tranh cãi.',
      c:'Dễ chưa chắc có tác động; bạn có thể xong nhiều việc mà mục tiêu vẫn đứng yên.',
      d:'Sở thích giúp làm hăng hơn, nhưng không nói việc nào đổi được kết quả.'} },
  { type:'mcq', stem:'Mục tiêu quý là khách ghé lần đầu. Thẻ thành viên tốn 40 giờ và chủ yếu giữ khách cũ. Bạn làm gì với việc này?',
    options:[{k:'a',t:'Làm ngay vì thẻ thành viên chuỗi nào cũng có, mình thiếu là tụt hậu'},{k:'b',t:'Làm một nửa trong tháng này, nửa còn lại làm dần cho xong'},
             {k:'c',t:'Tác động thấp với mục tiêu này, công sức cao: dời sang quý sau'},{k:'d',t:'Giao cho người mới để luyện tay, không tính vào 60 giờ của đội'}],
    answer:'c', why:{a:'"Ai cũng có" không phải lý do; câu hỏi là nó có đẩy được khách mới không.',
      b:'Làm một nửa thì chưa ra được gì mà vẫn ăn mất 20 giờ.',
      c:'Đúng. Việc tốt nhưng lệch mục tiêu thì để quý sau, khi mục tiêu là giữ khách.',
      d:'Giờ của người mới vẫn là giờ của đội; công sức không biến mất khi đổi người làm.'} },
  { type:'calc', stem:'Đội có 60 giờ. Bạn chọn sửa Google Maps (6 giờ) và TikTok (30 giờ). Còn lại bao nhiêu phần trăm quỹ giờ để dự phòng?',
    unit:'%', ans:40, tol:0.5, wrong:[[60,'SAI_TINH_TOAN'],[24,'NHAM_SO_TUYET_DOI']], errors:['SAI_TINH_TOAN','NHAM_SO_TUYET_DOI'],
    steps:['Giờ đã dùng = 6 + 30 = 36 giờ; còn lại 60 − 36 = 24 giờ.','Tỉ lệ dự phòng = 24 ÷ 60 = <b>40%</b>.'] },
  { type:'mcq', stem:'Việc nào thuộc góc "tác động thấp – công sức cao" với mục tiêu tăng khách mới cho quán?',
    options:[{k:'a',t:'Thuê ê-kíp quay phim thương hiệu 5 phút, đăng fanpage toàn khách quen theo dõi'},{k:'b',t:'Trả lời các đánh giá 1 sao đang nằm đầu trang Google Maps của từng quán'},
             {k:'c',t:'Đặt bảng "món mới" ra vỉa hè trước cửa những quán đông người qua lại'},{k:'d',t:'Cập nhật giờ mở cửa đang bị sai trên trang Google Maps của quán'}],
    answer:'a', why:{a:'Đúng. Tốn ê-kíp mà người xem chủ yếu là khách quen — gần như không kéo được khách mới.',
      b:'Ít giờ và khách lạ đọc đánh giá trước khi ghé: tác động cao, công sức thấp.',
      c:'Rẻ và chạm đúng người đi đường chưa từng vào quán.',
      d:'Vài phút sửa, tránh khách mới đến gặp cửa đóng: rất đáng làm.'} },
  { type:'mcq', stem:'Một đồng nghiệp chấm "tác động cao" cho việc đổi logo vì "trông chuyên nghiệp hơn". Bạn phản biện thế nào cho đúng trọng tâm?',
    options:[{k:'a',t:'Logo là chuyện của thiết kế, marketing không cần chấm việc này'},{k:'b',t:'Đổi logo phải in lại biển, ly, túi nên đây là việc tốn kém nhất danh sách'},
             {k:'c',t:'Chuyên nghiệp là tốt, vậy cứ cho điểm cao và làm song song'},{k:'d',t:'Hỏi: đổi logo làm tăng khách ghé lần đầu bằng cách nào, có bằng chứng gì?'}],
    answer:'d', why:{a:'Logo ảnh hưởng nhận diện, nên vẫn là việc cần chấm — chỉ là chấm theo mục tiêu.',
      b:'Công sức là trục kia; câu hỏi ở đây là tác động, và đồng nghiệp chưa chứng minh được.',
      c:'Chấm theo cảm giác làm ma trận mất giá trị: việc gì cũng thành cao.',
      d:'Đúng. Tác động phải nối được với mục tiêu bằng một cơ chế cụ thể.'} },
  { type:'mcq', stem:'Số minh hoạ: Maps tốn 6 giờ, ước thêm khoảng 30 khách mới mỗi tháng. TikTok tốn 30 giờ, ước khoảng 40 khách mới mỗi tháng nhưng chưa có dữ liệu. Đọc hai ước lượng này thế nào là hợp lý?',
    options:[{k:'a',t:'TikTok hơn vì 40 khách mới là nhiều hơn 30 khách mới mỗi tháng'},{k:'b',t:'Ngang nhau vì cùng tạo ra khoảng 30–40 khách mới mỗi tháng'},
             {k:'c',t:'TikTok hơn vì video còn tăng nhận diện nên không cần tính theo giờ'},{k:'d',t:'Maps hơn: khoảng 5 khách mỗi giờ so với 1,3; TikTok cần đo thêm trước khi tin'}],
    answer:'d', why:{a:'So số khách mà không chia cho giờ bỏ qua trục công sức: TikTok tốn gấp 5 lần giờ cho thêm 10 khách.',
      b:'Cùng đầu ra nhưng đầu vào chênh 5 lần; ma trận chấm cả hai trục.',
      c:'"Nhận diện" không đo được thì không chấm được; đây là cách đưa cảm giác trở lại bảng điểm.',
      d:'Đúng. Chia cho giờ ra 5 so với 1,3 khách mỗi giờ, và ước TikTok kém chắc chắn hơn nên cần mốc đo.'} },
  { type:'mcq', stem:'Sau một tháng, việc sửa Google Maps tưởng 6 giờ hoá ra mất 20 giờ vì chờ chủ quán duyệt ảnh. Bài học cho lần chấm sau?',
    options:[{k:'a',t:'Ước lượng sai là chuyện thường, không cần điều chỉnh gì'},{k:'b',t:'Lần sau đừng làm việc gì cần người khác duyệt nữa'},
             {k:'c',t:'Tính cả thời gian chờ và phụ thuộc vào trục công sức'},{k:'d',t:'Chuyển Maps sang góc "bỏ" vì đã tốn nhiều hơn dự tính'}],
    answer:'c', why:{a:'Không điều chỉnh thì lần sau lại lệch đúng kiểu cũ.',
      b:'Hầu hết việc đều cần duyệt; né thì không làm được gì.',
      c:'Đúng. Công sức gồm cả giờ chờ, giờ sửa, không chỉ giờ bấm máy.',
      d:'Việc đã xong và tác động vẫn cao; chấm lại công sức không làm nó thành việc nên bỏ.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:gt04-02', skill:'measure', read:'7 phút', t:'Ba ý tưởng tăng đơn cùng hấp dẫn: chấm điểm để chọn một thế nào?',
  situation:'Một shop giày thể thao trên Shopee có 3 ý tưởng: (1) thêm video thử giày ở trang sản phẩm, (2) tặng tất khi mua đôi thứ hai, (3) mở kênh livestream. Chủ shop thích livestream vì "đang hot". Bạn có 2 tuần và muốn chọn bằng lý lẽ, không phải bằng giọng to nhất trong phòng.',
  concept:{ name:'Chấm điểm ICE và RICE',
    body:'<b>ICE</b> chấm mỗi ý tưởng 1–10 ở ba mặt: Impact (tác động nếu thành công), Confidence (mức chắc chắn, dựa trên bằng chứng), Ease (dễ làm). Nhân ba số lại. <b>RICE</b> thêm Reach (bao nhiêu người chạm tới trong một kỳ) và dùng Effort (công sức) làm mẫu số: Reach × Impact × Confidence ÷ Effort. RICE hợp khi các ý tưởng chạm số người rất khác nhau. Con số không thay phán đoán; nó buộc mọi người nói rõ vì sao mình chấm cao.' },
  example:'Chấm RICE theo tháng. Video thử giày: chạm 8.000 người xem trang, tác động 2, chắc chắn 80% (đã thử video trên 5 mẫu tháng trước, tỉ lệ thêm giỏ tăng rõ), công sức 2 tuần-người → 8.000 × 2 × 0,8 ÷ 2 = 6.400. Livestream: chạm 1.500 người, tác động 3, chắc chắn 50%, công sức 4 → 562,5. Tặng tất: chạm 3.000, tác động 1, chắc chắn 80%, công sức 1 → 2.400. Video thắng rõ; livestream hot nhưng chạm ít và chưa chắc.',
  takeaway:'Chấm điểm không để ra đáp án thay bạn, mà để buộc mọi người nói ra bằng chứng đằng sau con số.',
  points:["Mỗi thành phần buộc người chấm trả lời một câu: bao nhiêu người, đổi bao nhiêu, bằng chứng gì, tốn công cỡ nào. Thiếu câu nào thì ý tưởng dễ được chọn vì nghe hay.","Điểm Confidence nên gắn với bằng chứng ghi lại: đã thử ở đâu, kết quả ra sao. Không có bằng chứng thì giữ ở mức thấp, dù cả phòng thấy ý tưởng hợp lý.","Hãy đem con số ra so với trực giác của đội. Nếu kết quả làm ai đó ngạc nhiên, đó là chỗ đáng thảo luận, vì một bên đang thiếu thông tin."],
  counter:"Giả sử livestream chỉ chạm 1.500 người trong tháng này nhưng người xem là khách mua đơn giá trị cao, và kênh còn kéo thêm người theo dõi sang các tháng sau. Reach hiện tại khi đó đánh giá thấp kênh này. Dấu hiệu nhận ra: điểm hạng nhất và hạng nhì sát nhau, hoặc Reach đổi mạnh giữa các tháng. Lúc ấy chạy thử nhỏ để mua thêm bằng chứng cho Confidence, rồi chấm lại.",
  deeper:"Người làm nghề dùng điểm để ra thứ tự thảo luận, không dùng làm phán quyết. Họ để ý đánh đổi: chấm kỹ thì tốn thời gian, chấm sơ thì dễ bị chi phối bởi ý tưởng được yêu thích. Bài này kề với chi phí cơ hội và kiểm rẻ nhất trước, vì Confidence thấp thường được nâng lên bằng một phép thử nhỏ. Tín hiệu cần theo dõi là khoảng cách điểm giữa các ý tưởng và độ lệch giữa người chấm. Kiểm tra trong tuần: nhờ hai người chấm riêng ba ý tưởng này theo cùng thang, so điểm Confidence, rồi hỏi mỗi người bằng chứng nào khiến họ chấm vậy.",
  apply:'Chọn hai ý tưởng đang tranh nhau trong đội bạn. Nói trong 60 giây: Reach, Impact, Confidence, Effort của mỗi cái là bao nhiêu và vì sao.',
  mistakes:['Cho Confidence cao chỉ vì mình thích ý tưởng, không có bằng chứng.','So điểm ICE giữa hai người chấm theo thang khác nhau.'],
  q:[
  { type:'mcq', stem:'Trước khi tính, bạn đoán ý tưởng nào thường bị chấm điểm cao quá tay nhất trong các buổi họp?',
    options:[{k:'a',t:'Ý tưởng rẻ, nhỏ, đã có đối thủ làm và có số liệu'},{k:'b',t:'Ý tưởng đã được thử một lần và cho kết quả đo được'},
             {k:'c',t:'Ý tưởng dễ làm nhất vì người ta hay đánh giá thấp việc dễ'},{k:'d',t:'Ý tưởng mới lạ, đang hot, người đề xuất có chức vụ cao'}],
    answer:'d', why:{a:'Loại này thường bị chấm thấp vì "không hấp dẫn", dù bằng chứng tốt.',
      b:'Đã có kết quả đo thì Confidence có căn cứ, ít bị thổi phồng.',
      c:'Việc dễ ít khi bị thổi phồng; vấn đề là nó hay bị xem nhẹ.',
      d:'Đúng. Độ mới và chức vụ làm Confidence và Impact bị đẩy lên mà không có bằng chứng.'} },
  { type:'mcq', stem:'Chủ shop muốn livestream, điểm RICE thấp nhất. Bạn chọn cách nào?',
    options:[{k:'a',t:'Làm video thử giày trước; đề xuất livestream thử nhỏ để tăng Confidence'},{k:'b',t:'Làm livestream vì chủ shop là người trả lương, điểm số chỉ để tham khảo'},
             {k:'c',t:'Bỏ hẳn livestream và không nhắc lại để khỏi tranh cãi thêm về chuyện này'},{k:'d',t:'Chấm lại cho livestream Confidence 90% để hai bên cùng vui'}],
    answer:'a', why:{a:'Đúng. Làm việc điểm cao trước, và biến nghi ngờ về livestream thành một phép thử rẻ.',
      b:'Bỏ qua bằng chứng thì chấm điểm để làm gì; chủ shop cần lý lẽ, không cần người chiều.',
      c:'Livestream có thể tốt; chỉ là chưa có bằng chứng. Một phép thử nhỏ trả lời được.',
      d:'Sửa số cho khớp ý sếp là phá cả công cụ; lần sau không ai tin điểm nữa.'} },
  { type:'calc', stem:'Ý tưởng X: Reach 5.000 người/tháng, Impact 2, Confidence 60%, Effort 3 tuần-người. Điểm RICE là bao nhiêu?',
    unit:'điểm', ans:2000, tol:1, wrong:[[18000,'SAI_TINH_TOAN'],[3333.3,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['RICE = Reach × Impact × Confidence ÷ Effort.','5.000 × 2 × 0,6 = 6.000; 6.000 ÷ 3 = <b>2.000</b>.'] },
  { type:'mcq', stem:'Khi nào nên dùng RICE thay vì ICE?',
    options:[{k:'a',t:'Khi đội chỉ có một người chấm và cần kết quả thật nhanh'},{k:'b',t:'Khi các ý tưởng chạm cùng một nhóm khách'},
             {k:'c',t:'Khi các ý tưởng chạm số người rất khác nhau'},{k:'d',t:'Khi muốn tránh phải ước lượng công sức cho từng ý tưởng một'}],
    answer:'c', why:{a:'Số người chấm không quyết định chọn công cụ nào.',
      b:'Reach như nhau thì thêm chữ R không đổi thứ hạng; ICE là đủ.',
      c:'Đúng. Reach tách riêng giúp không nhầm một ý tưởng "mạnh" nhưng chỉ chạm vài trăm người.',
      d:'RICE còn đòi ước lượng Effort kỹ hơn, không tránh được.'} },
  { type:'mcq', stem:'Hai người cùng chấm ICE: một người luôn cho 7–9, người kia cho 3–6. Vấn đề là gì?',
    options:[{k:'a',t:'Người chấm cao lạc quan hơn nên ý tưởng của họ tốt hơn'},{k:'b',t:'Thang điểm không thống nhất; phải định nghĩa mức 3, 6, 9 trước khi chấm'},
             {k:'c',t:'Nên lấy điểm cao nhất để không bỏ sót những ý tưởng có tiềm năng lớn'},{k:'d',t:'ICE không dùng được cho đội nhiều người, nên bỏ'}],
    answer:'b', why:{a:'Lạc quan không làm ý tưởng tốt hơn; nó chỉ làm điểm to hơn.',
      b:'Đúng. Không có mốc chung thì so điểm giữa hai người là so hai thang khác nhau.',
      c:'Lấy điểm cao nhất là thưởng cho người chấm rộng tay nhất.',
      d:'Công cụ vẫn dùng được; chỉ cần thống nhất mốc.'} },
  { type:'mcq', stem:'Một chuỗi trà sữa có ý tưởng A: ICE = 8 × 3 × 9. Ý tưởng B: 6 × 7 × 5. Nhận xét nào có ích nhất cho buổi họp?',
    options:[{k:'a',t:'A có Confidence 3: nên làm một phép thử rẻ để kiểm tra trước'},{k:'b',t:'A có tổng ba số cao hơn nên thắng, không cần bàn thêm'},
             {k:'c',t:'B đều tay ở cả ba mặt nên an toàn hơn và nên làm trước A'},{k:'d',t:'Hai điểm gần nhau nên bốc thăm cho nhanh'}],
    answer:'a', why:{a:'Đúng. A = 216, B = 210, gần ngang; điểm yếu của A là bằng chứng, và bằng chứng mua được bằng phép thử nhỏ.',
      b:'ICE nhân chứ không cộng; và 216 với 210 quá sát để gọi là thắng.',
      c:'Đều tay không có nghĩa phải đi trước; câu hỏi là mặt nào đang thiếu thông tin.',
      d:'Bốc thăm bỏ qua đúng chỗ có thể học: Confidence thấp của A.'} },
  { type:'mcq', stem:'Sau khi chấm, đội thấy ý tưởng hạng 1 không khả thi vì chưa có đủ ảnh sản phẩm. Nên làm gì?',
    options:[{k:'a',t:'Giữ nguyên thứ hạng và cứ làm, thiếu ảnh thì dùng ảnh mạng'},{k:'b',t:'Bỏ bảng điểm đi vì nó đã xếp sai ngay ý tưởng hạng 1'},
             {k:'c',t:'Làm ý tưởng hạng cuối cho an toàn vì ít phụ thuộc nhất'},{k:'d',t:'Chấm lại Ease/Effort cho đúng, xem thứ hạng có đổi không'}],
    answer:'d', why:{a:'Ảnh mạng có thể vi phạm bản quyền và làm hỏng niềm tin.',
      b:'Bảng điểm vừa làm đúng việc của nó: lộ ra một giả định sai.',
      c:'Hạng cuối có lý do để ở cuối; an toàn không phải tiêu chí.',
      d:'Đúng. Thông tin mới về công sức phải vào lại điểm; thứ hạng có thể đổi hoặc không.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:gt04-03', skill:'measure', read:'6 phút', t:'Nhận hợp đồng tài trợ sự kiện thì mất gì mà không ai ghi vào bảng?',
  situation:'Một thương hiệu nước mắm nhỏ ở Phú Quốc có 200 triệu cho quý này. Một ban tổ chức lễ hội ẩm thực mời tài trợ 120 triệu, hứa logo to và gian hàng. Cả đội hào hứng. Không ai hỏi: nếu tiêu 120 triệu ở đây, thì việc gì khác sẽ không được làm?',
  concept:{ name:'Chi phí cơ hội',
    body:'Mỗi đồng và mỗi giờ chỉ tiêu được một lần. <b>Chi phí cơ hội</b> của một lựa chọn là giá trị của phương án tốt nhất mà bạn phải bỏ vì chọn nó. Câu đúng không phải "việc này có lời không?" mà là "việc này có lời hơn việc tốt nhất mình phải bỏ không?". Một việc có lãi vẫn có thể là quyết định tồi nếu tiền đó đặt chỗ khác sinh lãi nhiều hơn.' },
  example:'Ước tính: tài trợ 120 triệu mang về khoảng 150 triệu lợi nhuận gộp từ đơn hàng và khách mới trong năm — lãi 30 triệu. Phương án tốt nhất phải bỏ: đưa sản phẩm vào 40 cửa hàng đặc sản ở TP.HCM, tốn 120 triệu phí lên kệ và trưng bày, ước lợi nhuận gộp 190 triệu — lãi 70 triệu. So với nhau, tài trợ kém hơn 40 triệu. Có lãi, nhưng không phải chỗ tốt nhất cho tiền.',
  takeaway:'Đừng hỏi việc này có lãi không; hãy hỏi nó có lãi hơn việc tốt nhất mình phải bỏ không.',
  points:["Chi phí cơ hội hiện ra khi bạn buộc mình nêu tên phương án bị bỏ. Không nêu tên thì cái giá chỉ nằm trong đầu và quyết định trông rẻ hơn thực tế.","Hai phương án nên được ước lượng theo cùng một cách và cùng một khoảng thời gian. So một con số kỹ với một con số phỏng đoán sẽ làm kết quả lệch.","Cái giá có thể là giờ người chứ không chỉ tiền. Dựng gian hàng lễ hội tốn nhiều ngày công của đội nhỏ, và những ngày đó không còn để theo dõi việc khác."],
  counter:"Giả sử phương án lên kệ cửa hàng đặc sản chưa nhận hàng trong quý này vì kệ đã kín. Khi đó phương án tốt nhất bị bỏ chỉ nằm trên giấy, và chi phí cơ hội của tài trợ là phương án thứ hai làm được thật. Dấu hiệu nhận ra: phương án kia cần điều kiện bạn chưa có, như kệ, người hay thời gian. Lúc ấy so tài trợ với phương án khả thi tốt nhất.",
  deeper:"Người làm nghề thấy chi phí cơ hội dễ bị lạm dụng thành cái cớ để chẳng chi gì: cứ so với một phương án lý tưởng thì việc nào cũng thua. Họ chỉ so với phương án có thể làm thật trong cùng quý. Bài này kề với phân bổ giữa giữ khách và tìm khách, vì cả hai đều hỏi tiền đi đâu thì có lợi hơn. Tín hiệu cần theo dõi là ước lượng của phương án bị bỏ có đủ bằng chứng hay chỉ là ý muốn. Kiểm tra trong tuần: viết hai cột cho khoản chi sắp duyệt, một cho nó, một cho phương án bị bỏ, kèm bằng chứng cho từng con số.",
  apply:'Nghĩ tới một khoản chi đội bạn vừa duyệt. Nói trong 60 giây: phương án tốt nhất đã bị bỏ là gì, và nó có thể mang lại bao nhiêu.',
  mistakes:['So một phương án với "không làm gì" thay vì với phương án tốt thứ hai.','Chỉ tính tiền, quên giờ người cũng có chi phí cơ hội.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc tiếp, theo bạn câu hỏi nào nên đặt đầu tiên khi được mời tài trợ 120 triệu?',
    options:[{k:'a',t:'Logo của mình sẽ to cỡ nào so với các nhà tài trợ lớn'},{k:'b',t:'Lễ hội năm ngoái đông bao nhiêu người, có lên báo không, có nghệ sĩ nổi tiếng nào tham gia'},
             {k:'c',t:'Nếu không tiêu 120 triệu ở đây, việc tốt nhất mình làm được là gì'},{k:'d',t:'Đối thủ có tài trợ không, nếu có thì mình cũng phải có'}],
    answer:'c', why:{a:'Kích cỡ logo là chi tiết của hợp đồng, chưa phải câu hỏi có nên làm không.',
      b:'Quy mô lễ hội giúp ước tác động, nhưng chưa so với phương án khác.',
      c:'Đúng. Đó là câu hỏi chi phí cơ hội: mốc để so sánh.',
      d:'Chạy theo đối thủ không trả lời tiền mình đặt ở đâu có lợi nhất.'} },
  { type:'mcq', stem:'Tài trợ lãi 30 triệu, lên kệ cửa hàng đặc sản lãi 70 triệu, cùng 120 triệu. Bạn đề xuất gì?',
    options:[{k:'a',t:'Nhận tài trợ vì có lãi, và sự kiện còn giúp thương hiệu được biết đến rộng rãi hơn trên mạng'},{k:'b',t:'Chia đôi 60 triệu cho mỗi bên để không bỏ lỡ cơ hội nào'},
             {k:'c',t:'Bỏ cả hai, giữ tiền cho an toàn đến cuối quý'},{k:'d',t:'Chọn lên kệ; chỉ nhận tài trợ nếu giảm giá hoặc ta nêu được giá trị khác'}],
    answer:'d', why:{a:'Có lãi chưa đủ; nó thua phương án kia 40 triệu. Lợi ích "được biết" phải được ước ra số mới so được.',
      b:'Tài trợ nửa gói thường không có quyền lợi nửa; lên kệ 20 cửa hàng cũng có thể không đủ để hàng quay vòng.',
      c:'Giữ tiền cũng có chi phí cơ hội: bỏ lỡ 70 triệu lãi.',
      d:'Đúng. Chọn phương án lãi hơn, và nói rõ điều kiện để tài trợ trở nên đáng.'} },
  { type:'calc', stem:'Phương án A lãi 30 triệu, phương án B (tốt nhất bị bỏ nếu chọn A) lãi 70 triệu. Chọn A thì thiệt bao nhiêu triệu so với B?',
    unit:'triệu', ans:40, tol:0.1, wrong:[[70,'NHAM_SO_TUYET_DOI'],[100,'SAI_TINH_TOAN']], errors:['NHAM_SO_TUYET_DOI','SAI_TINH_TOAN'],
    steps:['Chi phí cơ hội của A là lãi của B: 70 triệu.','Chênh lệch = 70 − 30 = <b>40 triệu</b>.'] },
  { type:'mcq', stem:'Một chuyên viên dành 3 ngày làm báo cáo đẹp không ai đọc. Chi phí cơ hội ở đây là gì?',
    options:[{k:'a',t:'Tiền in báo cáo và phí phần mềm thiết kế dùng trong ba ngày đó'},{k:'b',t:'Không có chi phí vì lương đã trả cố định hằng tháng'},
             {k:'c',t:'Sự khó chịu của người làm khi biết không ai đọc'},{k:'d',t:'Việc tốt nhất người đó đã có thể làm trong 3 ngày ấy'}],
    answer:'d', why:{a:'Chi phí trực tiếp có thể có, nhưng nhỏ so với ba ngày người.',
      b:'Lương cố định không làm giờ người miễn phí; giờ đã dùng thì không dùng lại được.',
      c:'Cảm xúc có thật nhưng không phải định nghĩa chi phí cơ hội.',
      d:'Đúng. Giờ người là nguồn lực khan hiếm; mất nó là mất việc có giá trị hơn.'} },
  { type:'mcq', stem:'Phép so sánh nào dễ làm một khoản chi trông hấp dẫn hơn thực tế?',
    options:[{k:'a',t:'So với phương án "không làm gì cả"'},{k:'b',t:'So với phương án tốt nhất tiếp theo có cùng ngân sách'},
             {k:'c',t:'So với kết quả của khoản chi tương tự năm trước'},{k:'d',t:'So lợi nhuận với chi phí tính đủ'}],
    answer:'a', why:{a:'Đúng. Gần như việc gì cũng hơn "không làm gì"; mốc này luôn làm lựa chọn trông tốt.',
      b:'Đây là mốc đúng của chi phí cơ hội.',
      c:'So với năm trước còn cho biết xu hướng, không thổi phồng bằng.',
      d:'Tính đủ chi phí làm con số thực tế hơn, không đẹp hơn.'} },
  { type:'mcq', stem:'Một tiệm bánh mì có 10 triệu. Lựa chọn: in 5.000 tờ rơi, hoặc lắp máy nướng để giảm thời gian chờ từ 8 xuống 3 phút giờ cao điểm. Bạn cần biết gì để so?',
    options:[{k:'a',t:'Ảnh hưởng của mỗi phương án lên doanh thu hay lợi nhuận trong cùng kỳ'},{k:'b',t:'Phương án nào nghe marketing hơn, dễ khoe thành tích với chủ tiệm trong buổi họp cuối tháng'},
             {k:'c',t:'Tờ rơi rẻ hơn mỗi tờ nên sẽ mang về lợi nhuận cao hơn'},{k:'d',t:'Máy móc không phải việc của marketing nên không đưa vào so sánh'}],
    answer:'a', why:{a:'Đúng. Hai lựa chọn khác loại nhưng so được nếu quy về cùng một thước: kết quả kinh doanh.',
      b:'"Nghe marketing" không phải thước đo.',
      c:'Giá mỗi tờ không nói gì về đơn thêm bao nhiêu.',
      d:'Chờ lâu làm mất khách đang xếp hàng; đó là việc của marketing theo nghĩa rộng.'} },
  { type:'mcq', stem:'Vì sao nói "có lãi" chưa đủ để chấp nhận một khoản chi marketing?',
    options:[{k:'a',t:'Vì khoản có lãi thường rủi ro hơn khoản hoà vốn'},{k:'b',t:'Vì tiền đó có thể đặt ở chỗ khác sinh lãi nhiều hơn'},
             {k:'c',t:'Vì lãi trong marketing khó đo nên chẳng đáng tin'},{k:'d',t:'Vì kế toán chỉ công nhận lãi sau khi kết thúc năm tài chính'}],
    answer:'b', why:{a:'Lãi và rủi ro không tỉ lệ theo kiểu đó.',
      b:'Đúng. Nguồn lực có hạn; cái giá thật là phương án tốt nhất bị bỏ.',
      c:'Khó đo không có nghĩa bỏ đo; ước lượng có căn cứ vẫn so được.',
      d:'Thời điểm ghi sổ không liên quan tới việc chọn giữa hai phương án.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:gt04-04', skill:'insight', read:'6 phút', t:'Một nhóm nhỏ khách mang về phần lớn doanh thu: dồn sức vào đâu?',
  situation:'Một nhà phân phối văn phòng phẩm ở Hà Nội có 500 khách doanh nghiệp. Đội sale 3 người chăm đều mỗi khách một cuộc gọi một tháng. Xuất dữ liệu ra, bạn thấy 100 khách lớn nhất mua 3,2 tỉ trong tổng 4 tỉ doanh thu năm. 400 khách còn lại mua 800 triệu.',
  concept:{ name:'Quy tắc 80/20 (nguyên lý Pareto)',
    body:'Trong nhiều doanh nghiệp, một phần nhỏ khách hoặc sản phẩm tạo ra phần lớn kết quả. Con số không nhất thiết đúng 80/20; có khi 70/30, có khi 90/10. Giá trị của quy tắc là buộc bạn <b>xếp hạng rồi nhìn</b> thay vì chia đều. Xếp theo lợi nhuận gộp sau chiết khấu và chi phí phục vụ, không chỉ theo doanh thu: khách lớn thường được giảm sâu. Nhưng cẩn thận: nhóm nhỏ hôm nay có thể là nhóm lớn ngày mai, và nhóm lớn cũng mang rủi ro tập trung — mất một khách lớn là mất nhiều.' },
  example:'Xếp hạng: 100 khách đầu (20%) mua 3,2 tỉ = 80% doanh thu. Mỗi khách lớn trung bình 32 triệu/năm, mỗi khách nhỏ 2 triệu. Đổi cách chăm: khách lớn gặp trực tiếp mỗi quý và có người phụ trách riêng; khách nhỏ chuyển sang đặt hàng qua Zalo OA và email định kỳ. Giờ gọi điện giảm một nửa, dành cho việc giữ và mở rộng đơn ở nhóm lớn. Nhưng xếp theo lãi mới đúng (số minh hoạ): khách lớn chiết khấu 15% và tốn chi phí phục vụ, 3,2 tỉ doanh thu chỉ còn 0,5 tỉ lãi; nhóm nhỏ 0,8 tỉ còn 0,25 tỉ. Lãi tập trung kém hơn doanh thu (khoảng 67%, không phải 80%), nhưng mỗi khách lớn vẫn lãi 5 triệu so với 0,6 triệu: mất một khách lớn bằng mất khoảng 8 khách nhỏ.',
  takeaway:'Xếp hạng trước khi chia sức; chăm đều mọi khách thường là chăm sai phần lớn.',
  apply:'Lấy danh sách khách hoặc sản phẩm của bạn, xếp theo doanh thu. Nói trong 60 giây: bao nhiêu phần trăm đầu bảng tạo ra bao nhiêu phần trăm doanh thu.',
  mistakes:['Bỏ mặc nhóm nhỏ hoàn toàn, quên rằng trong đó có khách đang lớn lên.','Tin con số 80/20 là luật cố định mà không đo trên dữ liệu của mình.'],
  q:[
  { type:'mcq', stem:'Đội sale 3 người gọi đều mỗi khách một cuộc mỗi tháng, bất kể khách mua nhiều hay ít. Bạn đoán cách chăm này đang gặp vấn đề gì?',
    options:[{k:'a',t:'Chăm đều là công bằng nên không có vấn đề gì đáng kể'},{k:'b',t:'Khách nhỏ bị chăm quá ít nên doanh thu của họ không tăng'},
             {k:'c',t:'Khách lớn nhận cùng mức quan tâm như khách mua rất ít'},{k:'d',t:'Đội sale quá đông so với số khách hiện có, cần cắt bớt người'}],
    answer:'c', why:{a:'Công bằng về cuộc gọi không phải công bằng về giá trị; đó chính là vấn đề.',
      b:'Khách nhỏ đang được chăm tương đương khách lớn, không phải quá ít.',
      c:'Đúng. Khách mang lại nhiều nhất không được chăm tương xứng.',
      d:'3 người cho 500 khách không phải đông; vấn đề là phân bổ.'} },
  { type:'mcq', stem:'100 khách lớn mua 80% doanh thu. Bạn làm gì với cách phân bổ giờ của đội sale?',
    options:[{k:'a',t:'Dồn gần hết giờ cho 100 khách lớn, nhóm nhỏ chỉ được xử lý khi họ tự gọi tới'},{k:'b',t:'Chăm sâu nhóm lớn, chuyển nhóm nhỏ sang kênh tự phục vụ và theo dõi ai đang lớn'},
             {k:'c',t:'Tăng cuộc gọi cho cả 500 khách lên hai lần mỗi tháng'},{k:'d',t:'Giữ nguyên vì thay đổi có thể làm khách nhỏ phật lòng'}],
    answer:'b', why:{a:'Nhóm nhỏ vẫn mang 800 triệu và có khách đang lớn; không kênh chủ động nào thì không ai thấy họ lớn.',
      b:'Đúng. Dồn sức vào nơi giá trị tập trung, vẫn giữ nhóm nhỏ bằng kênh rẻ.',
      c:'Đội 3 người không đủ giờ; và vẫn chia đều sai chỗ.',
      d:'Không thay đổi thì tiếp tục chăm sai phần lớn doanh thu.'} },
  { type:'calc', stem:'Tổng doanh thu 4 tỉ; 100 khách lớn mua 3,2 tỉ. Doanh thu trung bình mỗi khách trong 400 khách còn lại là bao nhiêu triệu?',
    unit:'triệu', ans:2, tol:0.01, wrong:[[8,'SAI_MAU_SO'],[1.6,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Doanh thu nhóm nhỏ = 4.000 − 3.200 = 800 triệu.','Chia cho 400 khách: 800 ÷ 400 = <b>2 triệu</b>.'] },
  { type:'mcq', stem:'Một khách lớn chiếm 25% doanh thu của nhà phân phối. Điều này nhắc bạn cần thêm gì?',
    options:[{k:'a',t:'Kế hoạch giảm rủi ro tập trung: giữ quan hệ sâu và phát triển thêm khách lớn khác'},{k:'b',t:'Giảm giá thật sâu cho khách này trên các đơn để họ không có lý do bỏ qua nơi khác'},
             {k:'c',t:'Không cần làm gì vì khách lớn thường rất trung thành'},{k:'d',t:'Chuyển khách này sang kênh tự phục vụ để tiết kiệm giờ sale cho khách khác'}],
    answer:'a', why:{a:'Đúng. 80/20 cũng là cảnh báo: phụ thuộc một khách thì mất họ là mất một phần tư.',
      b:'Giảm giá sâu làm mỏng lãi mà không chắc giữ được; khách lớn đi vì nhiều lý do khác ngoài giá.',
      c:'Khách lớn cũng là mục tiêu của đối thủ; trung thành không tự nhiên có.',
      d:'Ngược hoàn toàn: đây là khách cần chăm sâu nhất.'} },
  { type:'mcq', stem:'Số minh hoạ: khách lớn chiết khấu 15% cho ra 0,5 tỉ lãi trên 3,2 tỉ doanh thu; 400 khách nhỏ cho ra 0,25 tỉ lãi trên 0,8 tỉ. Điều chỉnh nào đúng khi phân bổ giờ sale?',
    options:[{k:'a',t:'Dồn sang khách nhỏ vì biên lãi 31% cao hơn hẳn biên 16% của khách lớn'},{k:'b',t:'Giữ nguyên ưu tiên cũ vì doanh thu chiếm 80% thì lãi cũng chiếm 80%'},
             {k:'c',t:'Hạ khách lớn xuống sau vì lãi mỏng, đổi sang chăm đều cho cả hai nhóm'},{k:'d',t:'Vẫn ưu tiên nhóm lớn (khoảng 2/3 lãi, 5 triệu mỗi khách), đồng thời giữ giá'}],
    answer:'d', why:{a:'Biên cao trên khoản nhỏ vẫn ra lãi tuyệt đối thấp: mỗi khách nhỏ lãi khoảng 0,6 triệu so với 5 triệu.',
      b:'Chiết khấu và chi phí phục vụ kéo lãi thấp hơn doanh thu; phải tính lại, đừng suy từ doanh thu.',
      c:'Biên mỏng không có nghĩa là nên bỏ: tổng lãi vẫn là 2/3 và mỗi khách lớn lãi gấp 8 lần.',
      d:'Đúng. Xếp theo lãi thì tập trung giảm nhưng vẫn rõ; việc thêm là bảo vệ biên bằng chính sách giá.'} },
  { type:'mcq', stem:'Dữ liệu của bạn cho ra 35% khách tạo 65% doanh thu, không phải 80/20. Kết luận nào đúng?',
    options:[{k:'a',t:'Dữ liệu sai vì phải ra đúng 80/20 mới chuẩn'},{k:'b',t:'Quy tắc không áp dụng được, nên quay lại chăm đều từng khách như trước'},
             {k:'c',t:'Doanh thu vẫn tập trung, chỉ ít hơn; phân bổ theo con số thật của mình'},{k:'d',t:'Phải tìm cách đẩy doanh thu về đúng tỉ lệ 80/20'}],
    answer:'c', why:{a:'80/20 là quy luật kinh nghiệm, không phải định luật.',
      b:'65% từ 35% khách vẫn là tập trung; chăm đều vẫn lệch.',
      c:'Đúng. Dùng tỉ lệ thật để quyết định, không dùng tỉ lệ trong sách.',
      d:'Không có lý do gì để nhắm tới một tỉ lệ đẹp.'} },
  { type:'mcq', stem:'Trong nhóm 400 khách nhỏ, có khách tăng đơn 3 lần trong 6 tháng. Nên xử lý thế nào?',
    options:[{k:'a',t:'Để nguyên trong kênh tự phục vụ cho đúng quy trình đã đặt'},{k:'b',t:'Đưa vào danh sách theo dõi, sale gọi tìm hiểu và cân nhắc nâng hạng'},
             {k:'c',t:'Giảm giá ngay để họ tiếp tục tăng'},{k:'d',t:'Bỏ qua vì trung bình nhóm nhỏ chỉ mua 2 triệu mỗi năm'}],
    answer:'b', why:{a:'Quy trình phục vụ mục tiêu, không phải ngược lại; khách đang lớn cần được thấy.',
      b:'Đúng. 80/20 là ảnh chụp; khách đang lớn là nhóm lớn tương lai.',
      c:'Chưa hiểu vì sao họ tăng mà đã giảm giá là đốt lãi.',
      d:'Trung bình che mất ngoại lệ; ngoại lệ đang tăng là tín hiệu quý.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:gt04-05', skill:'comm', read:'6 phút', t:'Việc tốt nhưng không quan trọng: nói "không" sao cho người ta vẫn nghe?',
  situation:'Bạn là marketing lead của một thương hiệu đồ gia dụng. Phòng kinh doanh xin làm bộ ảnh Tết cho 5 đại lý, phòng nhân sự xin video tuyển dụng, sếp tổng gợi ý làm podcast. Đội bạn 3 người đang dồn sức cho đợt ra mắt nồi chiên mới trong 6 tuần. Việc nào cũng hợp lý.',
  concept:{ name:'Nói "không" có cấu trúc',
    body:'Nói không không phải từ chối người, mà là bảo vệ ưu tiên đã thống nhất. Cấu trúc gọn: <b>ghi nhận</b> giá trị của đề xuất; <b>nêu ưu tiên</b> hiện tại và cái giá nếu nhận thêm; <b>đưa lựa chọn</b> — "không bây giờ" kèm thời điểm, làm bản nhỏ hơn, hoặc chỉ ra ai khác làm được. Người nghe chấp nhận dễ hơn khi thấy bạn đổi một cái lấy một cái, chứ không phải từ chối cho khỏi mệt. Khi bị ép bằng "đây là lệnh", đừng từ chối trống không: nhận lệnh, đưa hai phương án kèm hệ quả bằng văn bản để người quyết biết mình đổi gì.' },
  example:'Với phòng kinh doanh: "Bộ ảnh Tết cho đại lý đáng làm. Nhưng 6 tuần tới cả đội dồn cho nồi chiên; nhận thêm thì ra mắt trễ khoảng 2 tuần. Mình gửi lại 12 ảnh sản phẩm có sẵn để đại lý dùng tạm, và xếp bộ ảnh mới vào tuần thứ 7." Với sếp tổng: "Podcast cần khoảng 10 giờ mỗi tuần. Anh muốn đổi lấy việc gì trong đợt ra mắt?"',
  takeaway:'Nói "không bây giờ" kèm cái giá và một lựa chọn thay thế, không nói "không" trống trơn.',
  points:["Ghi nhận giá trị trước giúp người nghe thấy ý tưởng của họ được tôn trọng. Họ nhờ vậy dễ nghe phần sau, nơi bạn nêu giới hạn của đội.","Cái giá nên nói bằng đơn vị người nghe quan tâm: ra mắt trễ bao lâu, tốn bao nhiêu giờ. Giá cụ thể biến lời từ chối thành thông tin, không còn là thái độ.","Một lựa chọn thay thế có thời điểm hoặc bản nhỏ cho người xin một đường đi tiếp. Họ ra khỏi cuộc nói với một kế hoạch thay vì một cánh cửa đóng."],
  counter:"Giả sử phòng nhân sự cần video vì đợt tuyển gấp, và thiếu người trực đợt ra mắt nồi chiên mới. Khi đó việc này là điều kiện của kế hoạch. Dấu hiệu nhận ra: người xin chỉ ra được việc của họ chặn việc của bạn, kèm hạn chót. Lúc ấy đừng từ chối, hãy đàm phán phạm vi, ví dụ làm bản nhỏ hơn hoặc nhờ họ tự quay theo kịch bản bạn gửi.",
  deeper:"Người làm nghề coi nói không là chuyện của ngân sách quan hệ: từ chối nhiều thì mất thiện chí, nhận nhiều thì mất lịch. Họ giữ một danh sách yêu cầu đã dời kèm ngày hẹn để việc dời không bị quên. Bài này kề với ưu tiên theo mùa vụ và chi phí cơ hội. Tín hiệu cần theo dõi là số yêu cầu bị dời lặp lại mà không ai nhắc. Kiểm tra trong tuần: lấy một yêu cầu bạn đang ngại từ chối, viết ba câu theo cấu trúc ghi nhận, cái giá, lựa chọn, rồi đọc cho một đồng nghiệp xem họ nghe ra là đổi chứ không phải gạt.",
  apply:'Nghĩ tới một yêu cầu bạn đang ngại từ chối. Nói thành tiếng trong 60 giây theo ba bước: ghi nhận, nêu cái giá, đưa lựa chọn.',
  mistakes:['Nhận hết để làm vừa lòng rồi làm dở tất cả.','Từ chối mà không nêu cái giá, khiến người nghe thấy bị gạt đi.'],
  q:[
  { type:'mcq', stem:'Đội đang kín lịch 6 tuần ra mắt. Phòng chăm sóc khách xin bộ ảnh hướng dẫn vệ sinh nồi chiên (khoảng 2 ngày công). Câu trả lời nào dễ được chấp nhận nhất?',
    options:[{k:'a',t:'Bộ hướng dẫn rất cần. Đội đang kín lịch ra mắt nên chưa nhận được, mong chị thông cảm'},{k:'b',t:'Đội kín lịch ra mắt 6 tuần, nhận thêm thì ra mắt chậm khoảng 2 ngày, chị thông cảm giúp'},
             {k:'c',t:'Bộ hướng dẫn rất cần. Chị dùng tạm 8 ảnh có sẵn trong thư viện, còn lại cứ gửi yêu cầu qua nhóm'},{k:'d',t:'Bộ hướng dẫn rất cần; nhận thêm thì ra mắt chậm 2 ngày. Chị dùng tạm 8 ảnh có sẵn, mình làm bộ mới sau ra mắt'}],
    answer:'d', why:{a:'Có ghi nhận và nêu ưu tiên, nhưng không có cái giá cụ thể lẫn đường đi tiếp: người nghe chỉ nhận được "không".',
      b:'Có cái giá nhưng thiếu ghi nhận và thiếu lựa chọn; nghe như phàn nàn về tải việc hơn là một đề xuất.',
      c:'Có ghi nhận và lựa chọn, nhưng giấu cái giá và mốc: yêu cầu cứ chồng lên mà không ai biết cái nào lùi.',
      d:'Đúng. Đủ ba mảnh: ghi nhận, cái giá (chậm 2 ngày), lựa chọn có mốc (ảnh có sẵn, bộ mới sau ra mắt).'} },
  { type:'mcq', stem:'Sếp tổng gợi ý podcast giữa lúc đội dồn cho đợt ra mắt. Bạn chọn cách trả lời nào?',
    options:[{k:'a',t:'Nhận ngay vì là ý của sếp tổng'},{k:'b',t:'Nói podcast không hợp ngành đồ gia dụng nên đội chưa cần làm, mong sếp thông cảm'},
             {k:'c',t:'Nêu công sức podcast và hỏi sếp muốn đổi lấy việc nào trong kế hoạch'},{k:'d',t:'Im lặng chờ sếp quên'}],
    answer:'c', why:{a:'Nhận mà không nói cái giá thì đợt ra mắt trả giá, và sếp không biết.',
      b:'Gạt ý của sếp bằng một nhận định chưa có bằng chứng, và không nhắc gì tới cái giá hay lựa chọn.',
      c:'Đúng. Đặt lựa chọn lên bàn để sếp quyết với đủ thông tin.',
      d:'Sếp tổng hiếm khi quên; im lặng sẽ bị đọc là bất hợp tác.'} },
  { type:'calc', stem:'Đội 3 người, mỗi người 40 giờ/tuần, 80% giờ đang dành cho đợt ra mắt. Nếu nhận podcast 10 giờ/tuần, phần giờ còn lại cho mọi việc khác ngoài ra mắt và podcast là bao nhiêu giờ mỗi tuần?',
    unit:'giờ', ans:14, tol:0.1, wrong:[[24,'SAI_TINH_TOAN'],[30,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Tổng giờ = 3 × 40 = 120 giờ; ra mắt dùng 80% = 96 giờ.','Còn 120 − 96 = 24 giờ; trừ podcast 10 giờ = <b>14 giờ</b>.'] },
  { type:'mcq', stem:'Phòng nhân sự xin video tuyển dụng. Lựa chọn thay thế nào hợp lý nhất khi đội đang kín lịch?',
    options:[{k:'a',t:'Làm video thật nhanh trong một buổi, chất lượng thế nào cũng được'},{k:'b',t:'Gửi mẫu kịch bản và danh sách freelancer để nhân sự tự thuê'},
             {k:'c',t:'Hứa làm sau đợt ra mắt nhưng không ghi vào lịch'},{k:'d',t:'Nói việc tuyển dụng không phải việc của marketing nên từ chối hẳn'}],
    answer:'b', why:{a:'Video dở mang tên công ty có thể hại hình ảnh tuyển dụng.',
      b:'Đúng. Chỉ ra đường khác để việc vẫn được làm mà không lấy giờ của đội.',
      c:'Hứa không có lịch là cách nói "không" mà không dám nói.',
      d:'Hình ảnh nhà tuyển dụng có liên quan tới thương hiệu; gạt đi là mất đồng minh.'} },
  { type:'mcq', stem:'Sếp tổng nói thẳng: "Podcast là lệnh, bắt đầu tuần sau." Đội đang dồn cho đợt ra mắt, không còn giờ dư. Bạn trả lời thế nào?',
    options:[{k:'a',t:'Vâng, em làm ngay tuần sau, cả đội sẽ cố cân đối giờ để kịp cả hai việc anh giao'},{k:'b',t:'Podcast không làm được vì đội đang kín lịch theo đúng kế hoạch ra mắt anh đã duyệt'},
             {k:'c',t:'Em sẽ làm bản podcast tối thiểu vào những lúc có giờ, anh cứ yên tâm về đợt ra mắt'},{k:'d',t:'Em làm được; đây là hai phương án kèm hệ quả, anh chọn việc ra mắt nào lùi, em ghi lại gửi anh'}],
    answer:'d', why:{a:'Nhận lệnh mà không nói cái giá nghĩa là đợt ra mắt trả phí thầm lặng, và sếp không biết mình đã chọn gì.',
      b:'Từ chối thẳng một lệnh bằng "kế hoạch đã duyệt" biến cuộc trao đổi thành đối đầu và không cho sếp lối ra.',
      c:'"Khi nào có giờ" là không có lịch; hai việc vẫn tranh cùng một quỹ giờ mà không ai quyết cái nào trước.',
      d:'Đúng. Vẫn nhận lệnh, nhưng buộc quyết định đi kèm hệ quả, và có bằng chứng bằng văn bản.'} },
  { type:'mcq', stem:'Lúc nào thì nên nói "có" với một việc ngoài kế hoạch?',
    options:[{k:'a',t:'Khi người xin có chức vụ cao hơn mình, vì từ chối cấp trên thì về sau rất khó làm việc cùng nhau'},{k:'b',t:'Khi việc đó phục vụ mục tiêu chính tốt hơn việc đang làm, hoặc rất rẻ mà hỏng thì hại lớn'},
             {k:'c',t:'Khi việc đó nghe thú vị và cả đội đều muốn thử'},{k:'d',t:'Khi mình có thể làm ngoài giờ mà không ai biết'}],
    answer:'b', why:{a:'Chức vụ nâng tầm quan trọng của cuộc trao đổi, không tự nâng giá trị của việc.',
      b:'Đúng. Tiêu chí vẫn là mục tiêu và cái giá, không phải người xin.',
      c:'Thú vị không phải ưu tiên; nó dễ kéo đội khỏi mục tiêu.',
      d:'Làm ngoài giờ lâu dài làm đội kiệt sức và che mất cái giá thật.'} },
  { type:'mcq', stem:'Bạn đã từ chối một yêu cầu có hẹn "tuần thứ 7". Đến tuần thứ 7, đợt ra mắt kéo dài thêm. Bạn làm gì?',
    options:[{k:'a',t:'Báo sớm cho người đã xin, nêu lý do và hẹn mốc mới cụ thể'},{k:'b',t:'Lờ đi vì người kia có thể đã quên, không cần gợi lại'},
             {k:'c',t:'Làm vội cho xong trong lúc ra mắt để giữ lời, dù cả hai việc đều chất lượng thấp'},{k:'d',t:'Đổ lỗi cho sếp đã kéo dài đợt ra mắt'}],
    answer:'a', why:{a:'Đúng. "Không bây giờ" chỉ đáng tin khi mốc được giữ hoặc được báo đổi đàng hoàng.',
      b:'Lần sau lời hẹn của bạn sẽ không còn giá trị.',
      c:'Giữ lời bằng cách làm hỏng hai việc thì không giữ được gì.',
      d:'Đổ lỗi làm mất lòng tin của cả hai phía.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:gt04-06', skill:'comm', read:'7 phút', t:'Sếp muốn làm tất cả trong một quý: bạn trình bày thế nào?',
  situation:'Chủ một thương hiệu mỹ phẩm thuần chay giao cho đội 4 người trong quý 3: ra 2 dòng sản phẩm, mở gian hàng TikTok Shop, làm lại website, chạy 3 chiến dịch KOL và tham gia 2 hội chợ. Bạn ước tính tổng công sức khoảng 1.500 giờ, trong khi đội có khoảng 960 giờ trong quý.',
  concept:{ name:'Đưa sếp chọn giữa các kịch bản',
    body:'Khi sếp muốn tất cả, cãi "không làm nổi" hiếm khi hiệu quả. Hãy biến mong muốn thành <b>phép tính công khai</b>: tổng công sức cần, năng lực đang có, khoảng thiếu. Rồi đưa 2–3 <b>kịch bản</b>, mỗi kịch bản ghi rõ làm gì, bỏ gì, được kết quả gì. Quyết định vẫn là của sếp, nhưng sếp quyết trên con số thay vì trên hy vọng. Ước từng hạng mục theo giờ người, ghi biên sai số khoảng ±20% và nói rõ cái gì bị hoãn kèm rủi ro của việc hoãn. Thêm một kịch bản "làm hết nếu có thêm nguồn lực" để sếp thấy cái giá thật.' },
  example:'Ước từng hạng mục (số minh hoạ, sai số ±20%): 2 dòng sản phẩm 500 giờ, TikTok Shop 250, website 300, 3 KOL 270, 2 hội chợ 180; tổng 1.500, thiếu 540. Kịch bản A, tập trung doanh thu: 1 dòng sản phẩm 250 + TikTok Shop 250 + 3 KOL 270 + 1 hội chợ 90 = 860 giờ, dư 100 giờ đỡ sai số; hoãn website, rủi ro là trang cũ vẫn chuyển đổi 1,8%. Kịch bản B, tập trung nền tảng: website, 2 dòng sản phẩm, 1 KOL, khoảng 890 giờ; hoãn TikTok Shop. Kịch bản C: làm hết, thuê agency khoảng 540 giờ, ước 180 triệu. Sếp chọn A và giữ website cho quý 4.',
  takeaway:'Đừng cãi "không kịp"; hãy cho sếp thấy phép tính và vài kịch bản để chọn.',
  apply:'Lấy danh sách việc quý này của bạn. Nói trong 60 giây: tổng giờ cần, giờ đang có, và hai kịch bản bạn sẽ trình.',
  mistakes:['Nhận hết rồi âm thầm làm dở, đến cuối quý mới báo.','Chỉ đưa một kịch bản, khiến sếp thấy bị ép chứ không được chọn.'],
  q:[
  { type:'mcq', stem:'Theo bạn, cách phản hồi nào dễ khiến sếp chấp nhận cắt bớt việc nhất?',
    options:[{k:'a',t:'Nói thẳng "đội không làm nổi" và đề nghị tuyển thêm người'},{k:'b',t:'Nhận hết rồi làm từng việc, cái nào không kịp thì thôi, cuối quý báo cáo sau'},
             {k:'c',t:'Trình phép tính giờ và vài kịch bản ghi rõ đổi gì lấy gì'},{k:'d',t:'Kể về đội khác đã kiệt sức vì ôm quá nhiều việc'}],
    answer:'c', why:{a:'Kết luận không kèm con số dễ bị nghe như than vãn.',
      b:'Để lộ ra cuối quý thì đã muộn để chọn lại.',
      c:'Đúng. Con số và lựa chọn đưa quyết định về lại tay sếp một cách đàng hoàng.',
      d:'Câu chuyện gợi cảm xúc nhưng không cho sếp dữ kiện để chọn.'} },
  { type:'mcq', stem:'Sếp nghe xong nói: "Cố gắng thêm chút là được". Bạn làm gì tiếp?',
    options:[{k:'a',t:'Đồng ý và cho cả đội tăng ca mỗi tối cùng cuối tuần suốt quý để làm kịp hết kế hoạch'},{k:'b',t:'Chỉ ra 540 giờ thiếu tương đương hơn 2 người làm thêm cả quý, hỏi sếp chọn kịch bản nào'},
             {k:'c',t:'Im lặng rồi tự cắt những việc mình thấy ít quan trọng'},{k:'d',t:'Từ chối nhận kế hoạch cho đến khi sếp đồng ý tuyển thêm'}],
    answer:'b', why:{a:'Tăng ca vài tuần có thể; cả quý thì chất lượng và con người đều hỏng.',
      b:'Đúng. Quy khoảng thiếu thành đơn vị dễ hình dung rồi quay lại lựa chọn.',
      c:'Tự cắt mà không báo là lấy quyết định của sếp mà không có quyền.',
      d:'Đặt điều kiện cứng biến cuộc trao đổi thành đối đầu.'} },
  { type:'calc', stem:'Đội 4 người, mỗi người khoảng 20 giờ/tuần cho việc mới, quý có 12 tuần. Kế hoạch cần 1.500 giờ. Khoảng thiếu là bao nhiêu giờ?',
    unit:'giờ', ans:540, tol:1, wrong:[[1420,'SAI_TINH_TOAN'],[1260,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Năng lực = 4 × 20 × 12 = 960 giờ.','Khoảng thiếu = 1.500 − 960 = <b>540 giờ</b>.'] },
  { type:'mcq', stem:'Vì sao nên đưa thêm kịch bản "làm hết nếu thuê agency 180 triệu"?',
    options:[{k:'a',t:'Để sếp thấy cái giá thật của mong muốn làm tất cả'},{k:'b',t:'Để sếp chọn nó, vì thuê ngoài nhanh hơn làm trong'},
             {k:'c',t:'Để có sẵn lý do đổ lỗi nếu cuối quý không đạt mục tiêu'},{k:'d',t:'Vì kế hoạch nào cũng bắt buộc phải có đúng ba kịch bản'}],
    answer:'a', why:{a:'Đúng. Khi "làm hết" có giá cụ thể, sếp tự cân được nó có đáng không.',
      b:'Thuê ngoài cũng tốn giờ quản lý, và chưa chắc nhanh hơn.',
      c:'Kịch bản để giúp chọn, không phải để chuẩn bị đổ lỗi.',
      d:'Số kịch bản không có luật; ba chỉ là con số gọn thường dùng.'} },
  { type:'mcq', stem:'Một startup đồ ăn healthy: CEO muốn cùng lúc vào Shopee, Lazada, TikTok Shop và website riêng. Đội 2 người. Kịch bản nào nên nằm trong bản trình?',
    options:[{k:'a',t:'Mở cả bốn kênh cùng lúc nhưng mỗi kênh chỉ đăng vài sản phẩm'},{k:'b',t:'Chỉ làm website riêng vì đó là tài sản lâu dài của thương hiệu'},
             {k:'c',t:'Chờ tuyển đủ người rồi mới mở kênh nào'},{k:'d',t:'Bắt đầu một kênh nơi khách mục tiêu đông nhất, mở kênh thứ hai khi đạt mốc'}],
    answer:'d', why:{a:'Bốn kênh mỏng nghĩa là không kênh nào đủ đánh giá, đủ đơn để thuật toán đẩy.',
      b:'Website không có lượng người tự tìm đến; một thương hiệu mới cần nơi đã có khách.',
      c:'Chờ đủ người thì không bao giờ bắt đầu; bỏ lỡ cả quý.',
      d:'Đúng. Tuần tự có mốc cho phép đội nhỏ làm tốt một thứ rồi mới mở rộng.'} },
  { type:'mcq', stem:'Sếp chọn kịch bản A. Việc quan trọng nhất cần làm ngay sau cuộc họp là gì?',
    options:[{k:'a',t:'Bắt tay làm ngay, không cần ghi lại gì cho mất thời gian'},{k:'b',t:'Gửi email tóm tắt: làm gì, hoãn gì, đến bao giờ, ai đồng ý'},
             {k:'c',t:'Báo các phòng khác rằng marketing đã bị cắt việc'},{k:'d',t:'Đợi vài ngày xem sếp có đổi ý không rồi mới gửi kế hoạch chính thức'}],
    answer:'b', why:{a:'Không ghi lại thì vài tuần sau các việc bị hoãn lại xuất hiện như chưa từng bàn.',
      b:'Đúng. Văn bản giữ thoả thuận, và là mốc để bảo vệ ưu tiên khi có yêu cầu mới.',
      c:'Cách nói "bị cắt" gây hiểu nhầm; ưu tiên là do chọn, không phải bị ép.',
      d:'Kế hoạch chưa chốt thì đội làm trong mơ hồ, và các tuần đầu trôi đi mà thoả thuận chưa có chữ.'} },
  { type:'mcq', stem:'Giữa quý, sếp muốn thêm một hội chợ. Bạn phản hồi thế nào cho nhất quán?',
    options:[{k:'a',t:'Nhận vì chỉ là một sự kiện nhỏ'},{k:'b',t:'Từ chối vì kế hoạch đã chốt, không được thay đổi'},
             {k:'c',t:'Nêu giờ cần cho hội chợ và việc nào trong kịch bản A sẽ phải lùi'},{k:'d',t:'Nhận, rồi cuối quý giải thích vì sao TikTok Shop chưa đạt doanh số'}],
    answer:'c', why:{a:'"Nhỏ" nhưng một hội chợ tốn chuẩn bị, vận chuyển, đứng gian; phải tính ra giờ.',
      b:'Kế hoạch có thể đổi; vấn đề là đổi có ý thức về cái giá.',
      c:'Đúng. Dùng đúng cách đã dùng đầu quý: đổi cái gì lấy cái gì.',
      d:'Để cái giá lộ ra muộn là lặp lại lỗi cũ.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:gt04-07', skill:'measure', read:'6 phút', t:'Việc nhanh thắng hay việc nền tảng: đội nhỏ nên làm cái nào trước?',
  situation:'Một phòng khám nha khoa ở Cần Thơ muốn tăng lịch hẹn. Hai lựa chọn: (1) chạy ưu đãi cạo vôi 99.000 đồng trong 2 tuần, có lịch ngay; (2) xây hệ thống nhắc lịch tái khám qua Zalo, mất 6 tuần mới chạy, nhưng mỗi tháng sau đó tự mang về khách quay lại. Chủ phòng khám muốn thấy kết quả sớm.',
  concept:{ name:'Quick win và việc nền tảng',
    body:'<b>Quick win</b> cho kết quả nhanh, ít công, tạo niềm tin và dòng tiền. <b>Việc nền tảng</b> chậm ra kết quả nhưng cộng dồn: mỗi tháng sau lợi thêm. Đội chỉ làm quick win sẽ chạy mãi trên máy chạy bộ, vì mỗi đợt phải mua lại từ đầu; đội chỉ làm nền tảng có thể hết kiên nhẫn của sếp trước khi thấy quả. Cách hay dùng: làm một quick win để giữ đà và niềm tin, <b>song song</b> dành phần lớn sức cho một việc nền tảng.' },
  example:'Ưu đãi cạo vôi 99.000 đồng: khoảng 60 lịch trong 2 tuần, lãi chỉ cỡ 20.000 đồng mỗi lịch (số minh hoạ), tức 1,2 triệu, rồi hết khi ưu đãi dừng. Hệ thống nhắc tái khám: phòng khám có 1.200 bệnh nhân cũ; mỗi tháng nhắc 200 người và có thêm 20% quay lại so với khi không nhắc (đã trừ phần vẫn tự quay lại) là 40 lịch tăng thêm, khách trả giá đủ nên lãi cỡ 250.000 đồng mỗi lịch (minh hoạ): 10 triệu mỗi tháng. Nếu đếm lịch, ưu đãi thậm chí nhiều hơn; nếu đếm lãi, sau 6 tháng hệ thống nhắc đem 240 lịch, khoảng 60 triệu, còn ưu đãi lặp mỗi quý chỉ khoảng 2,4 triệu. Kế hoạch: chạy ưu đãi tuần 1–2 để có kết quả báo chủ, dành 70% giờ cho hệ thống nhắc lịch.',
  takeaway:'Dùng quick win để mua niềm tin, dùng niềm tin đó để làm việc nền tảng.',
  apply:'Chọn một mục tiêu của đội bạn. Nói trong 60 giây: một quick win và một việc nền tảng cho mục tiêu đó, và bạn chia sức giữa hai việc thế nào.',
  mistakes:['Chạy liên tục khuyến mãi vì mỗi lần đều "có số", mà không xây gì tích luỹ.','Làm nền tảng hàng tháng trời mà không báo được một kết quả sớm nào.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc tiếp, bạn đoán rủi ro lớn nhất của việc chỉ chạy ưu đãi liên tục là gì?',
    options:[{k:'a',t:'Hết ưu đãi là hết lịch, vì không có gì giữ khách quay lại ở giá đủ'},{k:'b',t:'Ưu đãi nào cũng bị đối thủ bắt chước ngay nên không tạo được lợi thế'},
             {k:'c',t:'Giá 99.000 đồng làm khách ngờ chất lượng kém nên ít người đặt lịch'},{k:'d',t:'Lịch tăng quá nhanh làm quá tải ghế và bác sĩ nên chất lượng khám giảm'}],
    answer:'a', why:{a:'Đúng. Mỗi đợt là một lần bơm, dừng là tắt; lại còn dạy khách quen chờ giá rẻ.',
      b:'Đối thủ có thể theo, nhưng đó là rủi ro cạnh tranh, không giải thích vì sao chỉ khuyến mãi thì không tích luỹ.',
      c:'Giá thấp đôi khi gây ngờ vực, nhưng ở ví dụ ưu đãi vẫn kéo được lịch; vấn đề là sau khi hết.',
      d:'Quá tải có thể xảy ra ngắn hạn, nhưng không phải vấn đề của chiến lược chỉ khuyến mãi.'} },
  { type:'mcq', stem:'Chủ phòng khám muốn thấy kết quả trong tháng này. Bạn chọn cách chia sức nào?',
    options:[{k:'a',t:'Chỉ chạy ưu đãi vì chủ cần thấy kết quả sớm, hệ thống nhắc lịch làm sau khi ổn định'},{k:'b',t:'Chỉ làm hệ thống nhắc lịch, giải thích chủ cần kiên nhẫn'},
             {k:'c',t:'Chạy ưu đãi 2 tuần để có số báo cáo, dành phần lớn giờ xây hệ thống nhắc lịch'},{k:'d',t:'Chờ đến khi có thêm người rồi làm cả hai'}],
    answer:'c', why:{a:'Làm chủ vui tháng này nhưng tháng sau lại bắt đầu từ số 0.',
      b:'6 tuần không có số nào dễ làm chủ mất kiên nhẫn và rút sự ủng hộ.',
      c:'Đúng. Quick win giữ niềm tin, nền tảng mang lại lợi cộng dồn.',
      d:'Chờ người thì cả hai đều trễ.'} },
  { type:'calc', stem:'Hệ thống nhắc lịch mỗi tháng nhắc 200 bệnh nhân cũ, có thêm 20% quay lại so với khi không nhắc. Sau 6 tháng chạy, tổng cộng có bao nhiêu lịch hẹn quay lại?',
    unit:'lịch', ans:240, tol:0.5, wrong:[[40,'NHAM_SO_TUYET_DOI'],[1200,'QUEN_TI_LE_CHUYEN_DOI']], errors:['NHAM_SO_TUYET_DOI','QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Mỗi tháng: 200 × 20% = 40 lịch.','Sau 6 tháng: 40 × 6 = <b>240 lịch</b>.'] },
  { type:'mcq', stem:'Việc nào dưới đây là việc nền tảng cho một shop quần áo online?',
    options:[{k:'a',t:'Flash sale cuối tuần giảm 30% cho cả cửa hàng'},{k:'b',t:'Thuê KOL đăng một video review'},
             {k:'c',t:'Treo banner "freeship hôm nay" trên trang chủ'},{k:'d',t:'Xây bảng size chuẩn và ảnh mặc thử để giảm đổi trả'}],
    answer:'d', why:{a:'Một đợt bán nhanh; hết sale là hết tác dụng.',
      b:'Một video mang lượt xem ngắn hạn; không tích luỹ trừ khi thành chuỗi.',
      c:'Ưu đãi một ngày là quick win điển hình.',
      d:'Đúng. Làm một lần, giảm đổi trả cho mọi đơn sau đó.'} },
  { type:'mcq', stem:'Một đội đã làm hệ thống email tự động 4 tháng mà chưa báo được con số nào. Rủi ro là gì và nên làm gì?',
    options:[{k:'a',t:'Không sao, việc nền tảng vốn chậm, cứ im lặng làm tiếp đến khi xong'},{k:'b',t:'Mất sự ủng hộ; nên chia nhỏ để đưa một phần chạy sớm và báo số đầu tiên'},
             {k:'c',t:'Bỏ dự án vì đã quá lâu'},{k:'d',t:'Chuyển sang chạy khuyến mãi để có số ngay'}],
    answer:'b', why:{a:'Im lặng lâu là cách nhanh nhất để dự án bị cắt trước khi xong.',
      b:'Đúng. Việc nền tảng cũng cần mốc sớm để chứng minh hướng đi đúng.',
      c:'Bốn tháng đã đầu tư; bỏ ngang là mất tất cả mà chưa kiểm tra.',
      d:'Đổi hướng hoàn toàn vì áp lực là quay lại vòng lặp quick win.'} },
  { type:'mcq', stem:'Quán lẩu giảm 20% giá mỗi cuối tuần. Lãi gộp vốn là 40% giá bán, và doanh số cuối tuần tăng 30%. So với không giảm giá, quick win này đem lại gì?',
    options:[{k:'a',t:'Lãi gộp giảm cỡ 35%: mỗi suất còn lãi 20 thay vì 40, bán nhiều hơn 30% vẫn không bù'},{k:'b',t:'Lãi gộp tăng, vì doanh số tăng 30% lớn hơn mức giảm giá 20%'},
             {k:'c',t:'Lãi gộp giảm đúng 20%, bằng mức giảm giá, vì chi phí vốn không đổi'},{k:'d',t:'Chưa tính được, vì chưa biết khách cuối tuần có quay lại ngày thường không'}],
    answer:'a', why:{a:'Đúng. Giá 100, vốn 60 → lãi 40; giảm 20% còn giá 80, lãi 20. Bán thêm 30%: 20 × 1,3 = 26 < 40. Muốn hoà lãi phải tăng 100% số suất.',
      b:'So 30% với 20% là quên rằng giảm giá ăn thẳng vào biên: lãi mỗi suất giảm một nửa chứ không giảm 20%.',
      c:'Giá giảm 20 thì lãi giảm đúng 20 đồng trên mức lãi 40, tức một nửa; vốn không đổi nên toàn bộ mức giảm trừ vào lãi.',
      d:'Khách quay lại là câu hỏi thêm; phép tính lãi trong chính đợt giảm giá đã đủ để thấy quick win này lỗ.'} },
  { type:'mcq', stem:'Vì sao việc nền tảng hay bị lùi mãi trong các đội nhỏ?',
    options:[{k:'a',t:'Vì việc nền tảng thường đắt hơn quick win về tiền'},{k:'b',t:'Vì sếp đội nhỏ ít khi muốn làm việc lâu dài'},
             {k:'c',t:'Vì nó không có hạn chót gấp, luôn thua việc gấp trước mắt'},{k:'d',t:'Vì việc nền tảng không đo được bằng số nên khó báo cáo'}],
    answer:'c', why:{a:'Nhiều việc nền tảng chủ yếu tốn giờ, không nhất thiết tốn tiền.',
      b:'Nhiều sếp muốn, nhưng mỗi tuần lại có việc gấp hơn.',
      c:'Đúng. Gấp luôn thắng quan trọng nếu không dành giờ cố định cho nền tảng.',
      d:'Việc nền tảng đo được, chỉ là kết quả đến chậm hơn.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:gt04-08', skill:'channel', read:'7 phút', t:'Tiền có hạn: chia cho giữ khách cũ hay tìm khách mới?',
  situation:'Một thương hiệu cà phê hạt rang bán online có 50 triệu mỗi tháng cho marketing, gần như dồn hết vào quảng cáo tìm khách mới. Chi phí có một khách mới khoảng 250.000 đồng. Dữ liệu cho thấy chỉ 25% khách mua lần hai. Chủ thương hiệu hỏi: có nên chuyển bớt tiền sang giữ khách?',
  concept:{ name:'Phân bổ giữa giữ khách và tìm khách',
    body:'Không có tỉ lệ đúng cho mọi nơi. Hãy so <b>chi phí thêm một đơn</b> từ mỗi hướng. Tìm khách mới: chi phí có khách ÷ số đơn họ mua. Giữ khách: chi phí chương trình ÷ số đơn quay lại thêm nhờ chương trình. Khi tỉ lệ mua lại thấp mà sản phẩm dùng hết phải mua tiếp (như cà phê), đồng tiền giữ khách thường rẻ hơn. Nhưng thương hiệu nhỏ vẫn cần dòng khách mới, vì khách cũ sẽ rời đi theo thời gian.' },
  example:'Chương trình nhắc mua lại: email và Zalo khi túi cà phê sắp hết, kèm mã giảm 10%, tốn khoảng 10 triệu/tháng cho 800 khách cũ. Thử 2 tháng: tỉ lệ mua lại từ 25% lên 35%, tức thêm 80 đơn mỗi tháng — khoảng 125.000 đồng mỗi đơn thêm. Tìm khách mới tốn 250.000 cho một đơn đầu. Đề xuất: chuyển 10 triệu sang giữ khách, 40 triệu vẫn cho khách mới, rồi đo tiếp.',
  takeaway:'So chi phí thêm một đơn của hai hướng; tiền đi về nơi đơn rẻ hơn, nhưng đừng tắt vòi khách mới.',
  points:["Đơn thêm mới là thứ cần so, vì khách cũ vốn đã mua lại một phần mà không cần chương trình. Chia chi phí cho cả nhóm làm giữ khách trông rẻ hơn thực tế.","Sản phẩm dùng hết thường tạo nhu cầu mua lại có chu kỳ. Nhắc đúng lúc gần hết túi thường rẻ hơn kéo một người lạ biết đến thương hiệu từ đầu.","Giữ phần tiền cho khách mới vì khách cũ rời đi dần theo thời gian. Nếu tắt hẳn, nguồn khách mới cạn và hướng giữ khách sẽ không còn ai để giữ."],
  counter:"Giả sử nhiều người mua túi cà phê này làm quà biếu và không tự dùng. Khi đó nhắc mua lại kèm mã giảm 10% ít khi tạo đơn thêm, vì họ không có chu kỳ hết hàng. Dấu hiệu nhận ra: tỉ lệ mua lại của nhóm mua quà gần như không đổi dù nhận chương trình. Lúc ấy tách nhóm mua quà khỏi nhóm uống hằng ngày, chỉ áp chương trình cho nhóm thứ hai.",
  deeper:"Người làm nghề thấy tỉ lệ chia giữa mới và cũ không phải hằng số: nó đổi theo vòng đời sản phẩm và mức bão hoà của kênh quảng cáo. Họ cũng để ý khách mới và khách giữ lại có giá trị lâu dài khác nhau, nên so một đơn chưa đủ. Bài này kề với chi phí cơ hội và phân rã doanh số theo số khách, số lần mua. Tín hiệu cần theo dõi là chi phí có khách mới, 250.000 đồng, có tăng dần khi dồn thêm tiền không. Kiểm tra trong tuần: trong 800 khách cũ, giữ một nhóm nhỏ không nhận chương trình, rồi so tỉ lệ mua lại sau vài tuần.",
  apply:'Nói trong 60 giây: đội bạn đang chia tiền giữa khách mới và khách cũ theo tỉ lệ nào, và bạn cần con số gì để biết tỉ lệ đó có đúng không.',
  mistakes:['Tính chi phí giữ khách chia cho toàn bộ khách cũ, kể cả người vốn tự mua lại.','Dồn hết sang giữ khách, để nguồn khách mới cạn dần.'],
  q:[
  { type:'mcq', stem:'Trước khi tính, bạn đoán vì sao thương hiệu cà phê này dễ có lợi khi đầu tư giữ khách?',
    options:[{k:'a',t:'Vì khách cũ thường ít nhạy giá nên không cần giảm giá gì'},{k:'b',t:'Vì quảng cáo tìm khách mới trên mạng xã hội sắp bị cấm'},
             {k:'c',t:'Vì cà phê dùng hết phải mua lại, mà tỉ lệ mua lại đang thấp'},{k:'d',t:'Vì khách cũ mua đơn giá trị gấp đôi khách mới'}],
    answer:'c', why:{a:'Khách cũ vẫn có thể nhạy giá; lý do ở đây là nhu cầu lặp lại.',
      b:'Không có căn cứ; đây là khẳng định bịa.',
      c:'Đúng. Nhu cầu lặp lại cộng tỉ lệ mua lại thấp là khoảng trống rẻ nhất để lấp.',
      d:'Con số gấp đôi không có trong dữ liệu; lý do ở đây là nhu cầu lặp lại.'} },
  { type:'mcq', stem:'Thử nghiệm cho thấy mỗi đơn thêm từ giữ khách tốn 125.000 đồng, khách mới 250.000 đồng. Bạn đề xuất gì?',
    options:[{k:'a',t:'Dồn cả 50 triệu sang giữ khách, vì chi phí mỗi đơn chỉ bằng nửa khách mới'},{k:'b',t:'Giữ nguyên vì thử nghiệm chỉ mới 2 tháng, chưa đủ tin'},
             {k:'c',t:'Tăng tổng ngân sách lên 100 triệu để làm cả hai cùng mạnh'},{k:'d',t:'Chuyển một phần sang giữ khách, vẫn giữ phần lớn cho khách mới và đo tiếp'}],
    answer:'d', why:{a:'800 khách cũ có trần; đổ thêm tiền không tạo thêm đơn tương ứng, và nguồn khách mới cạn.',
      b:'Hai tháng có kết quả rõ; không làm gì thì bỏ lỡ đơn rẻ hơn.',
      c:'Ngân sách có hạn là điều kiện đề bài; câu hỏi là chia thế nào.',
      d:'Đúng. Dịch dần theo bằng chứng, và giữ vòi khách mới chảy.'} },
  { type:'calc', stem:'Chương trình giữ khách tốn 10 triệu/tháng, làm 800 khách cũ mua lại từ 25% lên 35%. Chi phí cho mỗi đơn quay lại THÊM là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:125, tol:0.5, wrong:[[35.7,'TINH_TREN_KHACH_KHONG_HOAT_DONG'],[12.5,'SAI_MAU_SO']], errors:['TINH_TREN_KHACH_KHONG_HOAT_DONG','SAI_MAU_SO'],
    steps:['Đơn thêm = 800 × (35% − 25%) = 80 đơn.','Chi phí mỗi đơn thêm = 10.000.000 ÷ 80 = <b>125 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Một đồng nghiệp tính: 10 triệu ÷ 280 đơn mua lại = khoảng 36.000 đồng/đơn, "rẻ hơn khách mới gần 7 lần". Sai ở đâu?',
    options:[{k:'a',t:'Phải chia cho 800 khách cũ chứ không chia cho số đơn mua lại'},{k:'b',t:'Tính cả 200 đơn khách vẫn tự mua lại dù không có chương trình'},
             {k:'c',t:'Quên cộng chi phí quảng cáo tìm khách vào chương trình giữ khách'},{k:'d',t:'Không sai, cách tính này đúng và nên dùng khi báo cáo'}],
    answer:'b', why:{a:'Chia cho 800 còn lệch hơn; mẫu số đúng là đơn tăng thêm.',
      b:'Đúng. Chỉ 80 đơn là nhờ chương trình; 200 đơn kia vốn đã có.',
      c:'Chi phí quảng cáo khách mới không thuộc chương trình này.',
      d:'Tính vậy làm chương trình trông rẻ gấp ba lần thực tế.'} },
  { type:'mcq', stem:'Một chuỗi gym có tỉ lệ gia hạn 80% nhưng số hội viên mới mỗi tháng đang giảm. Hướng dồn thêm tiền hợp lý hơn là gì?',
    options:[{k:'a',t:'Tìm hội viên mới, vì phần giữ chân đã tốt còn nguồn vào đang cạn'},{k:'b',t:'Giữ khách thêm nữa, vì giữ khách rẻ hơn tìm khách mới'},
             {k:'c',t:'Cắt cả hai và dồn tiền vào sửa lại phòng tập cho đẹp hơn'},{k:'d',t:'Giảm giá gia hạn để đẩy tỉ lệ lên 95%'}],
    answer:'a', why:{a:'Đúng. Điểm nghẽn là nguồn vào; tiếp tục dồn vào chỗ đã tốt thì lợi thêm rất ít.',
      b:'"Giữ rẻ hơn tìm" là khẩu hiệu; ở mức 80% thì mỗi điểm thêm rất đắt.',
      c:'Phòng tập có thể cần sửa, nhưng không trả lời câu hỏi chia ngân sách.',
      d:'Giảm giá cho người vốn đã gia hạn là mất tiền trên chính 80% đó.'} },
  { type:'mcq', stem:'Vì sao không nên dồn toàn bộ ngân sách vào giữ khách dù chi phí mỗi đơn rẻ hơn?',
    options:[{k:'a',t:'Vì khách cũ hiếm khi phản hồi quá hai lần với một chương trình'},{k:'b',t:'Vì giữ khách chỉ hiệu quả trong mùa cao điểm, ngoài mùa thì khách cũ gần như không phản hồi'},
             {k:'c',t:'Vì khách cũ có trần và sẽ rời đi dần; không có khách mới thì tệp co lại'},{k:'d',t:'Vì kế toán không cho ghi chi phí giữ khách vào marketing'}],
    answer:'c', why:{a:'Không có quy luật "hai lần" như vậy.',
      b:'Giữ khách hiệu quả quanh năm với sản phẩm dùng lặp lại.',
      c:'Đúng. Hiệu quả giảm dần khi tệp đã được khai thác, và tệp tự hao hụt.',
      d:'Cách ghi sổ không phải lý do chiến lược.'} },
  { type:'mcq', stem:'Bạn muốn biết thật sự chương trình giữ khách tạo thêm bao nhiêu đơn. Cách đo đáng tin nhất là gì?',
    options:[{k:'a',t:'So doanh thu tháng này với tháng trước'},{k:'b',t:'Hỏi khách có thích chương trình không qua khảo sát ngắn gửi kèm đơn hàng'},
             {k:'c',t:'Đếm số người mở email nhắc mua lại'},{k:'d',t:'Chừa một nhóm khách cũ không nhận nhắc, so tỉ lệ mua lại hai nhóm'}],
    answer:'d', why:{a:'Doanh thu tháng lẫn mùa vụ, quảng cáo và nhiều thứ khác.',
      b:'Thích không có nghĩa là mua thêm.',
      c:'Mở email không phải mua; và người mở có thể vốn định mua.',
      d:'Đúng. Nhóm đối chứng cho biết phần mua lại tự nhiên, phần còn lại mới là nhờ chương trình.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:gt04-09', skill:'channel', read:'6 phút', t:'Mùa cao điểm sắp đến: dồn sức vào đâu và khi nào?',
  situation:'Một thương hiệu bánh trung thu handmade ở TP.HCM bán gần 70% doanh thu cả năm trong 5 tuần trước Tết Trung thu. Bây giờ còn 10 tuần. Đội 3 người đang dàn đều việc: đăng bài hằng ngày, làm lại website, chụp bộ ảnh Tết Nguyên đán, chăm khách doanh nghiệp.',
  concept:{ name:'Ưu tiên theo mùa vụ',
    body:'Khi doanh thu dồn vào một cửa sổ ngắn, thời điểm quan trọng không kém nội dung. Chia làm ba pha: <b>chuẩn bị</b> (trước mùa: sản phẩm, ảnh, đơn doanh nghiệp, kênh bán sẵn sàng), <b>thu hoạch</b> (trong mùa: dồn ngân sách và người vào bán, không làm việc mới), <b>sau mùa</b> (tổng kết, giữ khách, làm việc nền tảng). Việc nào không phục vụ mùa đang tới thì dời ra ngoài cửa sổ.' },
  example:'10 tuần còn lại: tuần 1–5 là chuẩn bị — chốt hộp quà, chụp ảnh sản phẩm trung thu, gửi báo giá cho 50 doanh nghiệp cũ (khách doanh nghiệp đặt sớm). Tuần 6–10 là thu hoạch — 80% ngân sách quảng cáo, đăng bài bán hàng, trực đơn. Website làm lại và ảnh Tết Nguyên đán dời sang sau Trung thu. Nếu năm ngoái doanh thu cả năm 2 tỉ, thì 5 tuần mùa mang khoảng 1,4 tỉ.',
  takeaway:'Trong mùa vụ, việc đúng làm sai thời điểm cũng là việc sai; xếp việc theo pha chuẩn bị – thu hoạch – sau mùa.',
  points:["Mùa vụ dồn doanh thu vào ít tuần, nên mỗi tuần dành cho việc không phục vụ mùa rất đắt. Xếp việc theo pha buộc bạn hỏi việc này cần xong trước hay sau mùa.","Pha chuẩn bị không chỉ để làm sẵn mà còn để chốt đơn đặt sớm. Khách doanh nghiệp thường quyết định sớm hơn khách lẻ, nên chờ tới mùa là mất họ.","Trong pha thu hoạch, mỗi thay đổi lớn mang rủi ro nhân đôi: sai sót ảnh hưởng ngay doanh thu và đội không còn thời gian sửa. Hãy chỉ giữ những gì đã thử."],
  counter:"Giả sử khách doanh nghiệp chốt phần lớn đơn ngay từ tuần chuẩn bị, và đối thủ đã tung ưu đãi sớm hơn kế hoạch. Khi đó pha chuẩn bị chính là pha bán, và để ngân sách bán tới tuần 6 mới chạy là quá muộn. Dấu hiệu nhận ra: lượng hỏi giá và đặt sớm tăng trước tuần 6, hoặc khách nói đã nhận báo giá nơi khác. Lúc ấy kéo một phần ngân sách bán lên sớm.",
  deeper:"Người làm nghề thấy đánh đổi giữa thu hoạch tối đa và xây nền: dời hết việc nền tảng ra sau mùa thì mùa sau lại thiếu đầu tư. Họ chọn một hai việc nền đáng giá nhất để làm ngay trong pha chuẩn bị. Bài này kề với nói không có cấu trúc và chi phí cơ hội, vì cả ba cùng xoay quanh việc tiền và giờ chỉ dùng được một lần. Tín hiệu cần theo dõi là số yêu cầu báo giá và đơn đặt sớm theo tuần so với năm trước. Kiểm tra trong tuần: liệt kê việc của đội, đánh dấu pha cho từng việc, và gạch bớt một việc nằm sai pha.",
  apply:'Chọn mùa cao điểm của ngành bạn. Nói trong 60 giây: 3 việc phải xong trước mùa, và 1 việc bạn sẽ dời ra sau mùa.',
  mistakes:['Bắt đầu chuẩn bị khi mùa đã tới, lúc đó giá quảng cáo và áp lực đều cao nhất.','Làm dự án lớn như đổi website ngay trước hoặc trong mùa.'],
  q:[
  { type:'mcq', stem:'Còn 10 tuần tới mùa bán chính. Bạn đoán việc nào nên dời đi đầu tiên?',
    options:[{k:'a',t:'Chăm khách doanh nghiệp cũ vì đó là việc ai cũng làm được'},{k:'b',t:'Chụp ảnh sản phẩm trung thu vì ảnh cũ năm ngoái vẫn dùng được'},
             {k:'c',t:'Chụp bộ ảnh Tết Nguyên đán, vì mùa đó còn cách xa'},{k:'d',t:'Chuẩn bị kênh bán vì đợi gần mùa hơn mới biết kênh nào tốt'}],
    answer:'c', why:{a:'Khách doanh nghiệp đặt sớm; đây là việc của pha chuẩn bị.',
      b:'Ảnh mới cho hộp quà năm nay là đồ nghề chính của mùa.',
      c:'Đúng. Không phục vụ mùa đang tới, lại tốn nhiều giờ.',
      d:'Chuẩn bị kênh muộn là mất tuần đầu của mùa.'} },
  { type:'mcq', stem:'Trưởng nhóm muốn làm lại website trong tuần 6–8 cho "kịp mùa". Bạn làm gì?',
    options:[{k:'a',t:'Làm, vì website mới đẹp hơn sẽ giúp bán được nhiều hơn trong mùa'},{k:'b',t:'Dời website sang sau mùa; chỉ sửa những lỗi đang cản đặt hàng'},
             {k:'c',t:'Làm song song cả website và bán hàng bằng cách tăng ca'},{k:'d',t:'Tắt website hẳn trong mùa, chỉ bán qua tin nhắn'}],
    answer:'b', why:{a:'Đổi hệ thống giữa mùa là rủi ro lỗi đúng lúc đơn nhiều nhất.',
      b:'Đúng. Trong mùa chỉ sửa chỗ cản đơn; việc lớn để sau.',
      c:'Tăng ca giữa mùa làm cả hai việc dễ hỏng.',
      d:'Tắt một kênh bán trong mùa là cắt chính dòng doanh thu.'} },
  { type:'calc', stem:'Năm ngoái doanh thu cả năm 2 tỉ, trong đó 70% bán trong 5 tuần mùa trung thu. Doanh thu trung bình mỗi tuần trong mùa là bao nhiêu triệu?',
    unit:'triệu', ans:280, tol:0.5, wrong:[[1400,'SAI_MAU_SO'],[38.5,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Doanh thu mùa = 2.000 × 70% = 1.400 triệu.','Mỗi tuần: 1.400 ÷ 5 = <b>280 triệu</b>.'] },
  { type:'mcq', stem:'Vì sao chăm khách doanh nghiệp nên nằm ở pha chuẩn bị chứ không phải trong mùa?',
    options:[{k:'a',t:'Vì doanh nghiệp thường duyệt ngân sách và đặt quà sớm, trong mùa phần lớn đã chốt'},{k:'b',t:'Vì doanh nghiệp ít dùng mạng xã hội nên gần như không thấy quảng cáo mùa trung thu'},
             {k:'c',t:'Vì đơn doanh nghiệp nhỏ hơn đơn lẻ nên không cần ưu tiên'},{k:'d',t:'Vì trong mùa đội quá bận, chỉ nên nhận đơn từ khách lẻ quen thuộc'}],
    answer:'a', why:{a:'Đúng. Chu kỳ quyết định của doanh nghiệp dài; đến mùa mới gọi là trễ.',
      b:'Người ra quyết định ở doanh nghiệp vẫn dùng mạng xã hội; lý do là thời điểm.',
      c:'Đơn doanh nghiệp thường lớn hơn nhiều; càng cần làm sớm.',
      d:'Bận không phải lý do bỏ khách lớn; là lý do làm sớm.'} },
  { type:'mcq', stem:'Một shop đồ bơi bán mạnh tháng 4–7. Tháng 10 nên dành sức cho việc gì?',
    options:[{k:'a',t:'Chạy quảng cáo đồ bơi mạnh vì giá quảng cáo đang rẻ'},{k:'b',t:'Tạm nghỉ, để dành sức đến tháng 3 năm sau'},
             {k:'c',t:'Dồn toàn lực ra thêm 20 mẫu đồ bơi mới cho kịp mùa sau nữa'},{k:'d',t:'Tổng kết mùa, giữ liên lạc khách cũ, làm việc nền tảng cho mùa sau'}],
    answer:'d', why:{a:'Rẻ nhưng nhu cầu thấp; tiền tiêu trái mùa sinh ít đơn.',
      b:'Mất khoảng thời gian tốt nhất để làm việc nền tảng.',
      c:'Ra mẫu mới có thể đúng, nhưng dồn toàn lực mà chưa tổng kết mùa vừa qua là làm mù.',
      d:'Đúng. Sau mùa là lúc rảnh tay cho việc mà trong mùa không làm được.'} },
  { type:'mcq', stem:'Trong mùa, đối thủ tung ưu đãi lớn. Nguyên tắc phản ứng hợp lý nhất là gì?',
    options:[{k:'a',t:'Lập tức giảm giá sâu hơn đối thủ để giữ khách, chuyện lãi lỗ tính sau khi hết mùa'},{k:'b',t:'Theo kịch bản đã chuẩn bị trước; chỉ đổi nếu số đơn giảm rõ theo ngày'},
             {k:'c',t:'Dừng quảng cáo để chờ đối thủ hết ưu đãi rồi mới chạy lại'},{k:'d',t:'Bắt đầu làm dòng sản phẩm mới ngay để cạnh tranh'}],
    answer:'b', why:{a:'Phản ứng theo cảm xúc giữa mùa dễ đốt hết lãi.',
      b:'Đúng. Pha chuẩn bị có kịch bản; dữ liệu đơn theo ngày quyết định có cần đổi không.',
      c:'Dừng giữa mùa là bỏ trống cửa sổ bán duy nhất.',
      d:'Làm sản phẩm mới giữa mùa không kịp và rối vận hành.'} },
  { type:'mcq', stem:'Đội muốn thử một kênh bán mới (TikTok Shop) cho mùa trung thu. Thời điểm thử nào hợp lý?',
    options:[{k:'a',t:'Ngay tuần đầu mùa, lúc có nhiều khách nhất để kết quả rõ ràng'},{k:'b',t:'Sau mùa, để không ảnh hưởng bất cứ điều gì trong năm nay'},
             {k:'c',t:'Trong pha chuẩn bị, đủ sớm để sửa lỗi trước khi mùa đến'},{k:'d',t:'Ở tuần cuối mùa, khi đơn đã bắt đầu giảm'}],
    answer:'c', why:{a:'Học giữa mùa là học lúc mỗi lỗi đắt nhất.',
      b:'Thử sau mùa thì không có nhu cầu để thử.',
      c:'Đúng. Thử sớm, sửa sớm, đến mùa chỉ việc đẩy.',
      d:'Tuần cuối nhu cầu đã giảm; kết quả không đại diện.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:gt04-10', skill:'measure', read:'6 phút', t:'Hai giả thuyết ngang điểm: chọn cái nào khi chỉ đủ tiền thử một?',
  situation:'Một app học tiếng Anh cho trẻ em có hai giả thuyết gần như ngang điểm ICE (tác động × tin cậy × dễ làm): (A) phụ huynh bỏ ở bước đăng ký vì form 9 trường quá dài, 5×6×7 = 210; (B) phụ huynh không tin vì thiếu đánh giá của phụ huynh khác, 8×5×5 = 200. Mỗi 2 tuần có 3.000 lượt vào trang, 1.500 người bấm đăng ký, chỉ 360 điền xong (số minh hoạ). Ngân sách đủ chạy một phép thử trong tháng. Cả đội chia hai phe.',
  concept:{ name:'Phá thế hoà giữa hai giả thuyết',
    body:'Khi điểm ngang nhau, đừng bốc thăm, và đừng cộng điểm lần hai: ICE đã chấm độ khó làm, nên tiêu chí phụ phải đem thông tin mới. Hỏi: <b>Cái nào cho đáp án đọc được sớm hơn?</b> — tính cả thời gian dựng lẫn thời gian chờ đủ mẫu. <b>Cái nào sai thì hại hơn?</b> — kiểm trước giả định mà nhiều kế hoạch khác dựa vào. <b>Cái nào mở khoá cái kia?</b> — nếu A thay đổi ai đến được B hoặc cách đo B, làm A trước. Vẫn ngang thì chọn cái đảo ngược được dễ hơn. Và mỗi lần chỉ đổi một biến.' },
  example:'Rút form từ 9 xuống 4 trường: lập trình viên làm 3 ngày, đọc kết quả sau 2 tuần, khoảng 2,5 tuần có đáp án. Thêm đánh giá phụ huynh (thu thập, xin phép đăng, thiết kế lại): 3 tuần dựng cộng 2 tuần đọc, khoảng 5 tuần. Đánh giá nằm ở bước sau form nên chỉ chạm người đã điền xong; 1.140 người (76%) bỏ ngay ở form thì B chưa với tới. A còn mở khoá B: nếu hoàn tất lên 18%, số người tới bước đánh giá tăng từ 360 lên 540, tức 1,5 lần mẫu để đo B. Và nếu rút form mà tỉ lệ vẫn thấp, đó là bằng chứng nút thắt là niềm tin. Chọn A trước.',
  takeaway:'Khi hoà điểm, thử cái cho đáp án sớm hơn, cái sai thì hại hơn, hoặc cái mở khoá cái còn lại.',
  apply:'Nghĩ tới hai ý tưởng đang ngang nhau trong đội bạn. Nói trong 60 giây: cái nào cho đáp án sớm hơn, cái nào mở khoá cái kia, và bạn chọn cái nào.',
  mistakes:['Bốc thăm hoặc theo phe đông người, bỏ qua chi phí kiểm.','Chạy cả hai thay đổi cùng lúc rồi không biết cái nào tạo ra kết quả.'],
  q:[
  { type:'mcq', stem:'Hai giả thuyết có ICE 210 và 200, gần như ngang nhau. Tiêu chí phụ nào đem lại thông tin mà ICE chưa tính?',
    options:[{k:'a',t:'Cộng thêm điểm cho giả thuyết có Impact cao hơn, vì tác động mới là điều quan trọng nhất'},{k:'b',t:'Chọn giả thuyết đã có nhiều dữ liệu cũ ủng hộ, vì độ tin cậy cao thì ít rủi ro'},
             {k:'c',t:'Chọn giả thuyết được nhiều người trong đội bỏ phiếu ủng hộ hơn sau buổi thảo luận'},{k:'d',t:'Chọn giả thuyết cho đáp án đọc được sớm hơn, vì mỗi tuần chờ là một tuần chưa học'}],
    answer:'d', why:{a:'Impact đã được tính trong 210 và 200; cộng lần nữa là đếm trùng và làm lệch bảng điểm có sẵn.',
      b:'Dữ liệu cũ đã nằm trong Confidence; chọn theo nó lần nữa là đếm trùng, và phép thử chắc thắng ít dạy được gì.',
      c:'Phiếu đo mức ủng hộ, không đo chi phí hay rủi ro; cũng là ý kiến chứ chưa phải bằng chứng.',
      d:'Đúng. Thời gian có đáp án (dựng cộng chờ đủ mẫu) là thứ ICE không thấy: A khoảng 2,5 tuần, B khoảng 5 tuần.'} },
  { type:'mcq', stem:'Rút form mất 3 ngày, thêm đánh giá mất 3 tuần. Đánh giá nằm sau form, và 76% người bắt đầu điền đã bỏ ngay ở form. Bạn chọn gì?',
    options:[{k:'a',t:'Chạy cả hai cùng lúc để tiết kiệm thời gian cho đội'},{k:'b',t:'Thêm đánh giá trước vì niềm tin là gốc rễ quyết định'},
             {k:'c',t:'Rút form trước: rẻ, nhanh, và gỡ nút thắt đứng trước'},{k:'d',t:'Chờ thêm dữ liệu một tháng nữa rồi quyết'}],
    answer:'c', why:{a:'Hai thay đổi cùng lúc thì không biết cái nào tạo ra kết quả.',
      b:'Có thể đúng, nhưng tốn gấp nhiều lần và chỉ chạm người đã qua form, trong khi 76% đã rơi ở đó.',
      c:'Đúng. Rẻ, nhanh và mở khoá việc đo giả thuyết B sạch hơn.',
      d:'Chờ không sinh thêm bằng chứng; phép thử mới sinh bằng chứng.'} },
  { type:'calc', stem:'Trang đăng ký có 3.000 lượt vào trong 2 tuần. Trước khi rút form, 12% hoàn tất; sau khi rút, 18%. Rút form mang thêm bao nhiêu lượt đăng ký?',
    unit:'lượt', ans:180, tol:0.5, wrong:[[540,'NHAM_SO_TUYET_DOI'],[6,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_SO_TUYET_DOI','NHAM_DIEM_PHAN_TRAM'],
    steps:['Trước: 3.000 × 12% = 360; sau: 3.000 × 18% = 540.','Thêm = 540 − 360 = <b>180 lượt</b>.'] },
  { type:'mcq', stem:'Tiêu chí "cái nào sai thì hại hơn" nghĩa là gì trong thực tế?',
    options:[{k:'a',t:'Kiểm trước giả định mà nhiều kế hoạch khác đang dựa vào'},{k:'b',t:'Chọn giả thuyết có khả năng sai thấp nhất để chắc thắng'},
             {k:'c',t:'Tránh giả thuyết nào có thể làm doanh thu giảm trong lúc thử nghiệm'},{k:'d',t:'Chọn giả thuyết mà sếp sẽ khó chịu nhất nếu sai'}],
    answer:'a', why:{a:'Đúng. Giả định gánh nhiều kế hoạch mà sai thì hỏng dây chuyền; kiểm sớm để khỏi xây trên cát.',
      b:'Chọn cái chắc đúng thì học được rất ít.',
      c:'Mọi phép thử đều có rủi ro nhỏ; tránh hết thì không thử được gì.',
      d:'Cảm xúc của sếp không phải thước đo tác hại.'} },
  { type:'mcq', stem:'Một quán bún bò có hai ý tưởng ngang điểm: đổi giờ mở cửa sớm hơn 1 tiếng, hoặc đổi biển hiệu mới. Nếu vẫn hoà sau các tiêu chí khác, chọn thế nào?',
    options:[{k:'a',t:'Biển hiệu, vì làm một lần dùng được nhiều năm'},{k:'b',t:'Giờ mở cửa, vì đảo ngược dễ nếu không hiệu quả'},
             {k:'c',t:'Làm cả hai cùng tuần để tiết kiệm thời gian'},{k:'d',t:'Hỏi khách quen thích cái nào hơn rồi làm theo số đông họ chọn'}],
    answer:'b', why:{a:'Dùng lâu cũng nghĩa là sai thì mắc lâu; biển hiệu khó đảo ngược.',
      b:'Đúng. Thử cái đảo ngược được trước: sai thì quay lại với chi phí nhỏ.',
      c:'Làm cùng lúc thì không tách được tác động.',
      d:'Khách quen không phản ánh khách chưa đến, và điều họ nói thích không đảm bảo hành vi; đo thử rẻ hơn hỏi.'} },
  { type:'mcq', stem:'Đội chạy cả hai thay đổi cùng lúc và đăng ký tăng 30%. Vấn đề là gì?',
    options:[{k:'a',t:'Không biết thay đổi nào tạo ra kết quả, nên không biết giữ gì bỏ gì'},{k:'b',t:'Không có vấn đề gì vì kết quả tốt là đủ'},
             {k:'c',t:'Kết quả 30% không tin được vì tăng quá nhiều'},{k:'d',t:'Chi phí đã gấp đôi so với chạy một thay đổi, nên dù tăng 30% vẫn lỗ'}],
    answer:'a', why:{a:'Đúng. Có thể một cái có lợi, một cái có hại; gộp thì không tách được. Chia 2×2 thì mỗi nhóm chỉ ~750 lượt, chỉ đọc được chênh lệch lớn.',
      b:'Tốt lần này, nhưng lần sau không biết lặp lại cái nào.',
      c:'Tăng nhiều không có nghĩa là sai; chỉ là không quy được nguyên nhân.',
      d:'Không đủ dữ kiện để kết luận lỗ.'} },
  { type:'mcq', stem:'Sau khi rút form, đăng ký tăng. Bước tiếp theo hợp lý với giả thuyết B là gì?',
    options:[{k:'a',t:'Bỏ B vì A đã giải quyết xong vấn đề'},{k:'b',t:'Chấm lại B với dữ liệu mới, rồi thử trên luồng đã có form ngắn'},
             {k:'c',t:'Làm B ngay cho cả tệp người dùng, khỏi cần đo'},{k:'d',t:'Quay lại form dài để thử B trong điều kiện giống lúc đầu'}],
    answer:'b', why:{a:'A giải quyết một nút thắt; niềm tin có thể là nút thắt tiếp theo.',
      b:'Đúng. Kết quả của A thay đổi bối cảnh; chấm lại rồi thử trên nền mới.',
      c:'Không đo thì không biết B có giúp không.',
      d:'Quay lại trạng thái kém hơn chỉ để thử là tự làm hại.'} }
  ] }

] });
